import { test, expect } from '@playwright/test';

test.describe('Debug Login Flow', () => {
  test('should show login page and print debug info', async ({ page }) => {
    await page.goto('http://localhost:3015/login');
    await page.waitForLoadState('networkidle');
    await page.waitForTimeout(2000);
    
    // Take screenshot for debugging
    await page.screenshot({ path: 'debug-login.png' });
    
    // Check what's on the page
    const title = await page.title();
    console.log('Page title:', title);
    
    // Look for form elements
    const inputs = await page.locator('input').all();
    console.log('Found', inputs.length, 'inputs');
    for (let i = 0; i < inputs.length; i++) {
      const type = await inputs[i].getAttribute('type');
      const placeholder = await inputs[i].getAttribute('placeholder');
      console.log(`Input ${i}: type=${type}, placeholder=${placeholder}`);
    }
    
    // Look for buttons
    const buttons = await page.locator('button').all();
    console.log('Found', buttons.length, 'buttons');
    for (let i = 0; i < buttons.length; i++) {
      const text = await buttons[i].innerText();
      console.log(`Button ${i}: ${text}`);
    }
    
    // Try to fill and submit
    const usernameInput = page.locator('input[type="text"], input[placeholder*="user"], input[placeholder*="name"]').first();
    const passwordInput = page.locator('input[type="password"]').first();
    const submitBtn = page.locator('button[type="submit"], button:has-text("Entrar"), button:has-text("Sign in")').first();
    
    console.log('Username input visible:', await usernameInput.isVisible());
    console.log('Password input visible:', await passwordInput.isVisible());
    console.log('Submit btn visible:', await submitBtn.isVisible());
    
    if (await usernameInput.isVisible()) {
      await usernameInput.fill('SENIOR');
      console.log('Filled username');
    }
    
    if (await passwordInput.isVisible()) {
      await passwordInput.fill('CHANGEPASSWORD');
      console.log('Filled password');
    }
    
    if (await submitBtn.isVisible()) {
      await submitBtn.click();
      console.log('Clicked submit');
      
      // Wait and check URL
      await page.waitForTimeout(3000);
      console.log('Current URL after submit:', page.url());
      
      // Take screenshot of result
      await page.screenshot({ path: 'debug-after-login.png' });
    }
  });
});

import { chromium } from "@playwright/test";

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  // Login via page
  await page.goto("http://localhost:3015/login");
  await page.waitForTimeout(2000);

  // Fill login form
  await page.fill('input[name="username"]', "SENIOR");
  await page.fill('input[name="password"]', "CHANGEPASSWORD");
  await page.click('button[type="submit"]');
  await page.waitForTimeout(3000);

  // Create free project via API
  const sessionCookies = page.context().cookies();
  const tokenResponse = await page.request.post("http://localhost:4410/api/v1/auth/login", {
    data: { username: "SENIOR", password: "CHANGEPASSWORD" },
  });
  const token = (await tokenResponse.json()).access_token;

  const create = await page.request.post("http://localhost:4410/api/v1/projects", {
    headers: { Authorization: `Bearer ${token}` },
    data: { name: "Test Social", project_kind: "free" },
  });
  const { id } = await create.json();

  // Navigate to project
  await page.goto(`http://localhost:3015/project/${id}`);
  await page.waitForTimeout(5000);

  // Check Excalidraw is loaded
  const container = await page.locator("[data-testid='excalidraw-container']").count();
  console.log("Container:", container);

  if (container === 0) {
    console.log("Excalidraw not loaded");
    await page.screenshot({ path: "e2e/error.png" });
    await browser.close();
    return;
  }

  // Open menu
  const menuBtn = page.locator(".excalidraw button").first();
  if (await menuBtn.count() > 0) {
    await menuBtn.click();
    await page.waitForTimeout(1500);
  }

  // Check social links
  const hasGitHub = await page.getByText("GitHub").isVisible({ timeout: 2000 }).catch(() => false);
  const hasDiscord = await page.getByText("Discord").isVisible({ timeout: 2000 }).catch(() => false);
  const hasFollow = await page.getByText("Follow us").isVisible({ timeout: 2000 }).catch(() => false);

  console.log("Social links:", { hasGitHub, hasDiscord, hasFollow });

  await page.screenshot({ path: "e2e/social-test.png", fullPage: true });
  console.log("Screenshot saved");

  await browser.close();
})();

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { api } from "@/lib/api";
import { renderEmbedSvg } from "@/lib/embed-svg";
import type { CanvasNodeData } from "@/lib/types";
import type { Edge, Node } from "@xyflow/react";

type Theme = "light" | "dark";

export default function EmbedPage() {
  const [graphId, setGraphId] = useState<string | null>(null);
  const [nodes, setNodes] = useState<Node<CanvasNodeData>[]>([]);
  const [edges, setEdges] = useState<Edge[]>([]);
  const [name, setName] = useState("");
  const [theme, setTheme] = useState<Theme>("dark");
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const svgRef = useRef<HTMLDivElement>(null);

  // Initialize from URL params without setState in effect
  const params = typeof window !== "undefined" ? new URLSearchParams(window.location.search) : null;
  const initialGraphId = params?.get("graph");
  const initialTheme = params?.get("theme");
  const resolvedTheme = initialTheme === "light" ? "light" : initialTheme === "dark" ? "dark" : "dark";
  const hasInitialId = !!initialGraphId;

  // Use useEffect only for side effects, not state initialization
  useEffect(() => {
    if (!hasInitialId) {
      // Already set loading=true in useState, no need to change
    }
  }, [hasInitialId]);

  useEffect(() => {
    if (!graphId) return;
    let cancelled = false;
    void (async () => {
      setLoading(true);
      setError(null);
      try {
        const payload = await api.getEmbed(graphId);
        if (cancelled) return;
        setName(payload.name);
        setNodes(payload.nodes as Node<CanvasNodeData>[]);
        setEdges(payload.edges as Edge[]);
      } catch (err) {
        if (cancelled) return;
        setError(err instanceof Error ? err.message : "Falha ao carregar diagrama");
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [graphId]);

  const origin =
    typeof window !== "undefined" ? window.location.origin : "https://archia.local";

  const embedResult = useMemo(() => {
    if (nodes.length === 0) {
      return {
        svg: "",
        iframeSnippet: graphId
          ? `<iframe src="${origin}/embed?graph=${graphId}&theme=${theme}" width="100%" height="600" frameborder="0" title="Archia diagram" loading="lazy"></iframe>`
          : "",
      };
    }
    const result = renderEmbedSvg(nodes, edges, { theme, width: 1400, height: 900 });
    const liveUrl = `${origin}/embed?graph=${graphId}&theme=${theme}`;
    const svgApi = `${process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:4410"}/api/v1/embed/${graphId}/svg?theme=${theme}`;
    return {
      ...result,
      iframeSnippet: `<iframe src="${liveUrl}" width="100%" height="600" frameborder="0" title="Archia ÔÇö ${name || "diagrama"}" loading="lazy" allowfullscreen></iframe>\n<!-- SVG est+ítico: ${svgApi} -->`,
    };
  }, [nodes, edges, theme, graphId, name, origin]);

  const svgCode = embedResult.svg;
  const iframeSnippet = embedResult.iframeSnippet;

  if (!graphId && !loading) {
    return (
      <div className="flex min-h-screen items-center justify-center p-8">
        <p className="text-sm text-[var(--muted-fg)]">
          Informe o par+ómetro <code className="rounded bg-white/5 px-1">?graph=ID</code> na URL.
        </p>
      </div>
    );
  }

  const isLight = theme === "light";

  return (
    <div className={`min-h-screen ${isLight ? "bg-slate-50 text-slate-900" : "bg-[var(--background)] text-[var(--foreground)]"}`}>
      <div
        className={`sticky top-0 z-10 border-b px-4 py-3 backdrop-blur ${
          isLight ? "border-slate-200 bg-white/95" : "border-[var(--border)] bg-[var(--surface-1)]/95"
        }`}
      >
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div>
            <h1 className={`text-sm font-semibold ${isLight ? "text-slate-900" : "text-slate-100"}`}>
              {name || "Diagrama Incorporado"}
            </h1>
            <p className={`text-xs ${isLight ? "text-slate-500" : "text-[var(--muted)]"}`}>
              Embed vivo -À {graphId ? `${graphId.slice(0, 8)}ÔÇª` : "ÔÇª"}
            </p>
          </div>
          <div className="flex items-center gap-2">
            <button
              type="button"
              className={`rounded px-2 py-1 text-xs ${theme === "light" ? "bg-indigo-600 text-white" : isLight ? "bg-slate-100 text-slate-700" : "bg-white/10 text-slate-300"}`}
              onClick={() => setTheme("light")}
            >
              Claro
            </button>
            <button
              type="button"
              className={`rounded px-2 py-1 text-xs ${theme === "dark" ? "bg-indigo-600 text-white" : isLight ? "bg-slate-100 text-slate-700" : "bg-white/10 text-slate-300"}`}
              onClick={() => setTheme("dark")}
            >
              Escuro
            </button>
            <button
              type="button"
              className="rounded bg-emerald-600 px-2 py-1 text-xs text-white disabled:opacity-50"
              disabled={!svgCode}
              onClick={() => {
                void navigator.clipboard.writeText(svgCode);
              }}
            >
              Copiar SVG
            </button>
          </div>
        </div>
      </div>

      <div ref={svgRef} className="p-4">
        {error ? (
          <div className="rounded-lg border border-rose-500/30 bg-rose-500/10 p-4 text-sm text-rose-300">
            {error}
          </div>
        ) : loading ? (
          <div className="flex h-64 items-center justify-center rounded-lg border border-dashed border-[var(--border-strong)]">
            <p className="text-sm text-[var(--muted)]">Carregando diagramaÔÇª</p>
          </div>
        ) : svgCode ? (
          <div
            className={`overflow-auto rounded-lg border elev-2 ${isLight ? "border-slate-200 bg-white" : "border-[var(--border)] bg-[var(--surface-1)]"}`}
            dangerouslySetInnerHTML={{ __html: svgCode }}
          />
        ) : (
          <div className="flex h-64 items-center justify-center rounded-lg border border-dashed border-[var(--border-strong)]">
            <p className="text-sm text-[var(--muted)]">Diagrama vazio.</p>
          </div>
        )}
      </div>

      {iframeSnippet && (
        <div className={`border-t p-4 ${isLight ? "border-slate-200" : "border-[var(--border)]"}`}>
          <p className={`mb-2 text-xs font-semibold uppercase ${isLight ? "text-slate-500" : "text-[var(--muted)]"}`}>
            Snippet para Notion / Confluence
          </p>
          <pre
            className={`overflow-x-auto rounded p-3 text-sm ${
              isLight ? "bg-slate-100 text-slate-700" : "bg-[var(--surface-1)] text-slate-300"
            }`}
          >
            {iframeSnippet}
          </pre>
          <p className={`mt-2 text-sm ${isLight ? "text-slate-500" : "text-[var(--muted)]"}`}>
            O iframe aponta para o embed vivo (SVG regenerado a cada carga). Use o endpoint{" "}
            <code className="rounded bg-black/5 px-1">/api/v1/embed/&#123;id&#125;/svg</code> para SVG est+ítico.
          </p>
        </div>
      )}
    </div>
  );
}

"use client";

import { ArrowLeft, Command, Home, RefreshCw } from "lucide-react";
import Link from "next/link";
import { useEffect, useState } from "react";

export default function NotFoundPage() {
  const [countdown, setCountdown] = useState(10);
  const [isDark, setIsDark] = useState(true); // Default matches SSR

  useEffect(() => {
    // Theme is already applied by layout.tsx inline script before React hydrates
    // No need to read localStorage here to avoid hydration mismatch

    const timer = setTimeout(() => {
      window.location.href = "/";
    }, 10000);

    const interval = setInterval(() => {
      setCountdown((prev) => {
        if (prev <= 1) {
          clearInterval(interval);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => {
      clearTimeout(timer);
      clearInterval(interval);
    };
  }, []);

  return (
    <div className={`flex min-h-screen items-center justify-center ${isDark ? "bg-[var(--background)]" : "bg-slate-50"}`}>
      {/* Background decoration */}
      <div className="pointer-events-none absolute inset-0 overflow-hidden">
        <div className={`absolute top-1/4 -left-32 h-96 w-96 rounded-full blur-3xl ${isDark ? "bg-indigo-500/10" : "bg-indigo-200/50"}`} />
        <div className={`absolute bottom-1/4 -right-32 h-96 w-96 rounded-full blur-3xl ${isDark ? "bg-purple-500/10" : "bg-purple-200/50"}`} />
      </div>

      <div className="relative z-10 mx-4 max-w-lg text-center">
        {/* Logo */}
        <div className="mb-8 flex justify-center">
          <div className={`flex h-16 w-16 items-center justify-center rounded-2xl ${isDark ? "bg-gradient-to-br from-indigo-400 to-indigo-600" : "bg-gradient-to-br from-indigo-500 to-indigo-700"} elev-3`}>
            <Command className={`h-8 w-8 ${isDark ? "text-slate-950" : "text-white"}`} />
          </div>
        </div>

        {/* 404 Number */}
        <h1 className={`mb-2 text-9xl font-black tracking-tighter ${isDark ? "text-white" : "text-slate-900"}`}>
          404
        </h1>

        {/* Subtitle */}
        <h2 className={`mb-3 text-2xl font-semibold ${isDark ? "text-white" : "text-slate-900"}`}>
          P+ígina n+úo encontrada
        </h2>

        <p className={`mb-8 text-base leading-relaxed ${isDark ? "text-slate-400" : "text-slate-600"}`}>
          Parece que esta p+ígina foi para um diagrama n+úo mapeado.<br />
          Vamos voltar para a seguran+ºa do dashboard.
        </p>

        {/* Action buttons */}
        <div className="mb-8 flex flex-col gap-3 sm:flex-row sm:justify-center">
          <Link
            href="/"
            className={`group inline-flex items-center justify-center gap-2 rounded-xl px-6 py-3 font-medium transition-all ${
              isDark
                ? "bg-indigo-600 text-white hover:bg-indigo-500"
                : "bg-indigo-600 text-white hover:bg-indigo-700"
            }`}
          >
            <Home className="h-4 w-4 transition-transform group-hover:-translate-y-0.5" />
            Voltar ao in+¡cio
          </Link>

          <button
            onClick={() => window.location.reload()}
            className={`inline-flex items-center justify-center gap-2 rounded-xl border px-6 py-3 font-medium transition-all ${
              isDark
                ? "border-slate-700 text-slate-300 hover:border-slate-600 hover:bg-slate-800/50"
                : "border-slate-200 text-slate-700 hover:border-slate-300 hover:bg-slate-50"
            }`}
          >
            <RefreshCw className="h-4 w-4 transition-transform hover:rotate-180" />
            Recarregar
          </button>
        </div>

        {/* Countdown hint */}
        <div className={`mx-auto flex max-w-xs items-center gap-2 rounded-lg border px-4 py-2.5 text-sm ${
          isDark ? "border-slate-800 bg-slate-900/50 text-slate-500" : "border-slate-200 bg-slate-50 text-slate-500"
        }`}>
          <span className="flex h-2 w-2 rounded-full bg-indigo-500 animate-pulse" />
          <span>
            Redirecionando em {countdown}s
          </span>
          <Link
            href="/"
            className={`ml-auto flex items-center gap-1 text-xs transition-colors ${
              isDark ? "text-slate-400 hover:text-indigo-400" : "text-slate-500 hover:text-indigo-600"
            }`}
          >
            <ArrowLeft className="h-3 w-3" />
            Agora
          </Link>
        </div>

        {/* Help text */}
        <p className={`mt-6 text-xs ${isDark ? "text-slate-600" : "text-slate-400"}`}>
          Se o problema persistir, verifique a URL ou entre em contato com o suporte.
        </p>
      </div>
    </div>
  );
}

"use client";

import NewProjectModal from "@/components/dashboard/NewProjectModal";
import ProjectCard from "@/components/dashboard/ProjectCard";
import ProjectFilters from "@/components/dashboard/ProjectFilters";
import FirstProjectWizard from "@/components/onboarding/FirstProjectWizard";
import { useProjectStore } from "@/lib/project-store";
import {
  AlertTriangle,
  Archive,
  ArchiveX,
  FolderKanban,
  Globe2,
  LayoutDashboard,
  Layers,
  Network,
  Pin,
  Plus,
  Search,
  Trash2,
  X,
} from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";

type Stats = {
  total: number;
  pinned: number;
  archived: number;
  public: number;
  nodes: number;
};

export default function DashboardPage() {
  const {
    projects,
    isLoading,
    filters,
    setFilters,
    loadProjects,
    createProject,
    deleteProject,
    archiveProject,
    pinProject,
  } = useProjectStore();

  const [modalOpen, setModalOpen] = useState(false);
  const [wizardOpen, setWizardOpen] = useState(false);
  const [wizardDismissed, setWizardDismissed] = useState(() => {
    // Initialize from localStorage to avoid hydration mismatch
    try {
      const onboarded = localStorage.getItem("archia-onboarded");
      return onboarded === "1";
    } catch {
      return false;
    }
  });
  const [searchDraft, setSearchDraft] = useState("");
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const router = useRouter();

  const refresh = useCallback(() => void loadProjects(), [loadProjects]);

  // Load projects on mount (this is a side effect, not state sync)
  useEffect(() => {
    void refresh();
  }, [refresh]);

  useEffect(() => {
    const t = setTimeout(() => {
      setFilters({ search: searchDraft });
      void loadProjects({ search: searchDraft });
    }, 250);
    return () => clearTimeout(t);
  }, [searchDraft, setFilters, loadProjects]);

  const stats = useMemo<Stats>(() => {
    const all = projects;
    return {
      total: all.length,
      pinned: all.filter((p) => p.pinned).length,
      archived: all.filter((p) => p.archived).length,
      public: all.filter((p) => p.is_public).length,
      nodes: all.reduce((sum, p) => sum + (p.node_count ?? 0), 0),
    };
  }, [projects]);

  const shownProjects = useMemo(
    () => projects.filter((p) => (filters.archived ? p.archived : !p.archived)),
    [projects, filters.archived],
  );

  return (
    <div className="flex min-h-0 flex-1 flex-col overflow-hidden">
      <header className="shrink-0 border-b border-[var(--border)] bg-[var(--background)]/90 px-6 py-4 backdrop-blur">
        <div className="flex items-start justify-between gap-4">
          <div className="flex items-start gap-3">
            <div className="mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-[var(--accent-muted)] text-[var(--accent)]">
              <LayoutDashboard className="h-5 w-5" />
            </div>
            <div>
              <h1 className="text-base font-semibold tracking-tight text-slate-100">Dashboard</h1>
              <p className="mt-0.5 flex items-center gap-1.5 text-xs text-[var(--muted)]">
                <FolderKanban className="h-3 w-3" />
                Gerencie seus projetos de arquitetura
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={() => setModalOpen(true)}
            className="inline-flex shrink-0 items-center gap-2 rounded-xl bg-[var(--accent)] px-4 py-2 text-sm font-semibold text-[var(--accent-fg)] shadow transition hover:bg-[var(--accent-hover)]"
          >
            <Plus className="h-4 w-4" />
            Novo projeto
          </button>
        </div>
      </header>

      <div className="flex min-h-0 flex-1 flex-col overflow-hidden px-6 py-5">
        <div className="grid grid-cols-2 gap-3 pb-5 sm:grid-cols-4">
          <StatCard
            label="Projetos"
            value={stats.total}
            icon={<Layers className="h-4 w-4 text-indigo-400" />}
            subIcon={<Pin className="h-3 w-3" />}
            sub={`${stats.pinned} fixados`}
          />
          <StatCard
            label="N+¦s no total"
            value={stats.nodes}
            icon={<Network className="h-4 w-4 text-emerald-400" />}
            subIcon={<Layers className="h-3 w-3" />}
            sub="diagramas"
          />
          <StatCard
            label="P+¦blicos"
            value={stats.public}
            icon={<Globe2 className="h-4 w-4 text-amber-400" />}
            subIcon={<Globe2 className="h-3 w-3" />}
            sub="compartilh+íveis"
          />
          <StatCard
            label="Arquivados"
            value={stats.archived}
            icon={<ArchiveX className="h-4 w-4 text-[var(--muted-fg)]" />}
            subIcon={<Archive className="h-3 w-3" />}
            sub={filters.archived ? "visualizando" : "ocultos"}
          />
        </div>

        <div className="mb-4 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <div className="flex flex-1 flex-wrap items-center gap-3">
            <div className="relative max-w-xs flex-1 min-w-[180px]">
              <Search className="pointer-events-none absolute top-1/2 left-2.5 h-3.5 w-3.5 -translate-y-1/2 text-[var(--muted)]" />
              <input
                value={searchDraft}
                onChange={(e) => setSearchDraft(e.target.value)}
                placeholder="Buscar projetosÔÇª"
                className="w-full rounded-lg border border-[var(--border)] bg-black/30 py-2 pr-3 pl-8 text-sm focus:outline-none focus:ring-2 focus:ring-[var(--accent)] placeholder:text-[var(--muted-fg)] focus:border-[var(--accent)]"
              />
              {searchDraft && (
                <button
                  type="button"
                  onClick={() => setSearchDraft("")}
                  className="absolute top-1/2 right-2 -translate-y-1/2 rounded p-0.5 text-[var(--muted)] hover:text-slate-200"
                  aria-label="Limpar busca"
                >
                  <X className="h-3.5 w-3.5" />
                </button>
              )}
            </div>
            <ProjectFilters
              filters={filters}
              onChange={(partial) => {
                setFilters(partial);
                void loadProjects(partial);
              }}
            />
          </div>
          <button
            type="button"
            onClick={() => {
              setFilters({ archived: !filters.archived });
              void loadProjects({ archived: !filters.archived });
            }}
            className={`inline-flex shrink-0 items-center gap-1.5 rounded-lg border px-3 py-2 text-xs font-medium transition ${
              filters.archived
                ? "border-amber-500/30 bg-amber-500/10 text-amber-200"
                : "border-[var(--border)] text-[var(--muted-fg)] hover:border-[var(--accent)]/40 hover:bg-[var(--accent-muted)]"
            }`}
          >
            {filters.archived ? <FolderKanban className="h-3.5 w-3.5" /> : <ArchiveX className="h-3.5 w-3.5" />}
            {filters.archived ? "Mostrar ativos" : "Ver arquivados"}
          </button>
        </div>

        <div className="flex-1 overflow-y-auto">
          {isLoading && projects.length === 0 ? (
            <div className="grid grid-cols-1 gap-4 p-1 sm:grid-cols-2 lg:grid-cols-3">
              {Array.from({ length: 6 }).map((_, i) => (
                <div key={i} className="rounded-xl border border-[var(--border)] bg-[var(--surface-1)] p-4">
                  <div className="skeleton mb-3 h-5 w-2/3" />
                  <div className="skeleton mb-2 h-3 w-full" />
                  <div className="skeleton h-3 w-4/5" />
                </div>
              ))}
            </div>
          ) : shownProjects.length === 0 ? (
            <EmptyState search={searchDraft} archived={!!filters.archived} onCreate={() => setModalOpen(true)} />
          ) : (
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
              {!filters.archived && (
                <button
                  type="button"
                  onClick={() => setModalOpen(true)}
                  className="group flex min-h-[160px] flex-col items-center justify-center gap-2 rounded-xl border border-dashed border-[var(--border-strong)] bg-transparent text-[var(--muted)] transition hover:border-[var(--accent)]/40 hover:bg-[var(--accent-muted)] hover:text-indigo-300"
                >
                  <span className="flex h-10 w-10 items-center justify-center rounded-full bg-white/5">
                    <Plus className="h-5 w-5" />
                  </span>
                  <span className="inline-flex items-center gap-1.5 text-sm font-medium">
                    <FolderKanban className="h-3.5 w-3.5" />
                    Novo projeto
                  </span>
                </button>
              )}
              {shownProjects.map((p) => (
                <ProjectCard
                  key={p.id}
                  project={p}
                  onPin={() => void pinProject(p.id)}
                  onArchive={() => void archiveProject(p.id)}
                  onDelete={() => setConfirmDeleteId(p.id)}
                />
              ))}
            </div>
          )}
        </div>
      </div>

      <NewProjectModal
        open={modalOpen}
        onClose={() => setModalOpen(false)}
        onSubmit={async (data) => {
          const created = await createProject(data);
          setModalOpen(false);
          void loadProjects();
          router.push(`/project/${created.id}`);
        }}
      />

      <FirstProjectWizard
        open={wizardOpen}
        onClose={() => {
          setWizardOpen(false);
          setWizardDismissed(true);
          try {
            localStorage.setItem("archia-onboarded", "1");
          } catch {
            /* ignore */
          }
        }}
        onComplete={async (data) => {
          const created = await createProject({
            name: data.name,
            description: data.description,
            context: data.context,
          });
          setWizardDismissed(true);
          try {
            localStorage.setItem("archia-onboarded", "1");
          } catch {
            /* ignore */
          }
          return created.id;
        }}
      />

      {confirmDeleteId && (
        <ConfirmDialog
          title="Excluir projeto?"
          description="Remove o projeto e todos os diagramas. N+úo d+í para desfazer."
          confirmLabel="Excluir"
          onConfirm={() => {
            void deleteProject(confirmDeleteId).then(() => setConfirmDeleteId(null));
          }}
          onCancel={() => setConfirmDeleteId(null)}
        />
      )}
    </div>
  );
}

function StatCard({
  label,
  value,
  icon,
  sub,
  subIcon,
}: {
  label: string;
  value: number;
  icon: React.ReactNode;
  sub?: string;
  subIcon?: React.ReactNode;
}) {
  return (
    <div className="rounded-xl border border-[var(--border)] bg-[var(--surface-2)] p-4">
      <div className="flex items-center justify-between">
        <span className="text-xs font-medium text-[var(--muted)]">{label}</span>
        <span className="flex h-7 w-7 items-center justify-center rounded-lg bg-white/5">{icon}</span>
      </div>
      <p className="mt-2 text-2xl font-semibold text-slate-100">{value}</p>
      {sub && (
        <p className="mt-0.5 inline-flex items-center gap-2 text-sm text-[var(--muted-fg)]">
          {subIcon}
          {sub}
        </p>
      )}
    </div>
  );
}

function EmptyState({
  search,
  archived,
  onCreate,
}: {
  search: string;
  archived: boolean;
  onCreate: () => void;
}) {
  return (
    <div className="flex flex-col items-center justify-center gap-3 py-20 text-center">
      <div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-white/5">
        {archived ? (
          <ArchiveX className="h-6 w-6 text-[var(--muted)]" />
        ) : search ? (
          <Search className="h-6 w-6 text-[var(--muted)]" />
        ) : (
          <FolderKanban className="h-6 w-6 text-[var(--muted)]" />
        )}
      </div>
      <div>
        <p className="text-sm font-medium text-slate-300">
          {archived
            ? "Nenhum projeto arquivado."
            : search
              ? "Nenhum projeto encontrado."
              : "Nenhum projeto ainda."}
        </p>
        <p className="mt-1 text-xs text-[var(--muted)]">
          {archived
            ? "Restaurando projetos os torna vis+¡veis novamente."
            : search
              ? "Tente ajustar os filtros ou a busca."
              : "Comece criando sua primeira arquitetura."}
        </p>
      </div>
      {!archived && (
        <button
          type="button"
          onClick={onCreate}
          className="mt-2 inline-flex items-center gap-2 rounded-xl bg-[var(--accent)] px-4 py-2 text-sm font-medium text-[var(--accent-fg)] hover:bg-[var(--accent-hover)]"
        >
          <Plus className="h-4 w-4" />
          Criar projeto
        </button>
      )}
    </div>
  );
}

function ConfirmDialog({
  title,
  description,
  confirmLabel,
  onConfirm,
  onCancel,
}: {
  title: string;
  description: string;
  confirmLabel: string;
  onConfirm: () => void;
  onCancel: () => void;
}) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm" onClick={(e) => { if (e.target === e.currentTarget) onCancel(); }}>
      <div className="w-full max-w-sm rounded-2xl border border-[var(--border)] bg-[var(--surface-2)] p-5 elev-4">
        <div className="mb-3 flex h-10 w-10 items-center justify-center rounded-xl bg-rose-500/15 text-rose-300">
          <AlertTriangle className="h-5 w-5" />
        </div>
        <h3 className="text-base font-semibold text-slate-100">{title}</h3>
        <p className="mt-2 text-sm text-[var(--muted-fg)]">{description}</p>
        <div className="mt-5 flex justify-end gap-2">
          <button
            type="button"
            onClick={onCancel}
            className="inline-flex items-center gap-1.5 rounded-lg px-3 py-2 text-sm text-[var(--muted-fg)] hover:bg-white/5"
          >
            <X className="h-3.5 w-3.5" />
            Cancelar
          </button>
          <button
            type="button"
            onClick={onConfirm}
            className="inline-flex items-center gap-1.5 rounded-lg bg-rose-500/90 px-3 py-2 text-sm font-medium text-white hover:bg-rose-500"
          >
            <Trash2 className="h-3.5 w-3.5" />
            {confirmLabel}
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import Image from "next/image";
import { useAuthStore } from "@/lib/auth-store";
import { maskPhone } from "@/lib/masks";
import {
  AlertTriangle,
  BadgeCheck,
  CalendarDays,
  Camera,
  CheckCircle2,
  Crop,
  IdCard,
  Mail,
  Pencil,
  Phone,
  Save,
  Shield,
  Timer,
  User,
  UserCircle,
  X,
} from "lucide-react";
import { useEffect, useRef, useState } from "react";

type CropState = {
  x: number;
  y: number;
  width: number;
  height: number;
};

export default function ProfilePage() {
  const { user, isLoading, fetchProfile, updateProfile, setAvatarUrl } = useAuthStore();
  const avatarUrl = user?.avatar_url ?? null;
  const [editing, setEditing] = useState(false);
  const [form, setForm] = useState({ username: "", email: "", phone: "" });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState(false);

  const [showCrop, setShowCrop] = useState(false);
  const [cropState, setCropState] = useState<CropState>({ x: 0, y: 0, width: 100, height: 100 });
  const [cropImage, setCropImage] = useState<string | null>(null);
  const [cropping, setCropping] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Auto-save settings
  const [autoSaveEnabled, setAutoSaveEnabled] = useState(true);
  const [autoSaveInterval, setAutoSaveInterval] = useState(15);

  useEffect(() => {
    void fetchProfile();
  }, [fetchProfile]);

  // Load avatar from localStorage on mount if not in store
  useEffect(() => {
    if (!avatarUrl) {
      try {
        const saved = localStorage.getItem("archia-user-avatar");
        if (saved) {
          setAvatarUrl(prev => prev || saved);
        }
      } catch {
        // ignore
      }
    }
  }, [avatarUrl]);

  async function save() {
    setSaving(true);
    setError(null);
    setSuccess(false);
    try {
      const ok = await updateProfile({
        username: form.username,
        email: form.email,
        phone: form.phone || undefined,
        auto_save_enabled: autoSaveEnabled,
        auto_save_interval_minutes: autoSaveInterval,
      });
      if (ok) {
        setSuccess(true);
        setEditing(false);
        setTimeout(() => setSuccess(false), 2000);
      } else {
        setError("Falha ao salvar perfil");
      }
    } catch {
      setError("Falha ao conectar ao servidor");
    } finally {
      setSaving(false);
    }
  }

  async function handleAvatarChange(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;

    // Validate file type
    const allowedTypes = ["image/png", "image/jpeg", "image/webp", "image/avif", "image/gif"];
    if (!allowedTypes.includes(file.type)) {
      setError("Formato n+úo suportado. Use PNG, JPEG, WebP, AVIF ou GIF.");
      return;
    }

    // Validate file size (max 10MB)
    if (file.size > 10 * 1024 * 1024) {
      setError("Imagem muito grande. M+íximo 10MB.");
      return;
    }

    const url = URL.createObjectURL(file);
    setCropImage(url);
    setShowCrop(true);
    // Reset crop to full image
    setCropState({ x: 0, y: 0, width: 100, height: 100 });
  }

  function applyCrop() {
    setCropping(true);
    // Create canvas to crop the image
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement("canvas");
      const ctx = canvas.getContext("2d");
      if (!ctx) {
        setCropping(false);
        return;
      }

      // Calculate how the image is displayed in the container (object-cover)
      const containerRatio = 1; // aspect-square
      const imgRatio = img.naturalWidth / img.naturalHeight;

      let sourceX = 0;
      let sourceY = 0;
      let sourceWidth = img.naturalWidth;
      let sourceHeight = img.naturalHeight;

      // When image is wider than container (landscape), we see only center portion
      if (imgRatio > containerRatio) {
        // Image is wider - visible height = full container height
        // Visible width = container height (because aspect-square)
        // The image is centered, so we see the middle portion
        sourceHeight = img.naturalHeight;
        sourceWidth = img.naturalHeight * containerRatio; // = img.naturalHeight (since ratio=1)
        sourceX = (img.naturalWidth - sourceWidth) / 2;
      } else if (imgRatio < containerRatio) {
        // Image is taller - visible width = full container width
        // Visible height = container width (because aspect-square)
        sourceWidth = img.naturalWidth;
        sourceHeight = img.naturalWidth / containerRatio; // = img.naturalWidth
        sourceY = (img.naturalHeight - sourceHeight) / 2;
      }

      // Convert crop percentages (relative to container) to image coordinates
      // The container shows sourceX..sourceX+sourceWidth of the image
      const cropX = sourceX + (sourceWidth * cropState.x) / 100;
      const cropY = sourceY + (sourceHeight * cropState.y) / 100;
      const cropW = (sourceWidth * cropState.width) / 100;
      const cropH = (sourceHeight * cropState.height) / 100;

      // Clamp to image bounds
      const safeX = Math.max(0, Math.min(cropX, img.naturalWidth - 1));
      const safeY = Math.max(0, Math.min(cropY, img.naturalHeight - 1));
      const safeW = Math.min(cropW, img.naturalWidth - safeX);
      const safeH = Math.min(cropH, img.naturalHeight - safeY);

      canvas.width = Math.max(1, Math.round(safeW));
      canvas.height = Math.max(1, Math.round(safeH));

      // Draw cropped image
      ctx.drawImage(
        img,
        safeX,
        safeY,
        safeW,
        safeH,
        0,
        0,
        canvas.width,
        canvas.height,
      );

      const dataUrl = canvas.toDataURL("image/jpeg", 0.95);
      setAvatarUrl(dataUrl);
      setCropping(false);
      setShowCrop(false);
      if (cropImage) URL.revokeObjectURL(cropImage);
    };
    img.onerror = () => {
      setCropping(false);
    };
    img.src = cropImage;
  }

  function skipCrop() {
    setShowCrop(false);
    if (cropImage) URL.revokeObjectURL(cropImage);
  }

  function removeAvatar() {
    setAvatarUrl(null);
  }

  if (isLoading || !user) {
    return (
      <div className="flex min-h-full items-center justify-center">
        <div className="h-7 w-7 animate-spin rounded-full border-2 border-[var(--accent)]/30 border-t-[var(--accent)]" />
      </div>
    );
  }

  return (
    <div className="flex min-h-0 flex-1 flex-col overflow-hidden">
      <header className="shrink-0 border-b border-[var(--border)] bg-[var(--background)] px-6 py-4">
        <div className="flex items-center gap-3">
          <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[var(--accent-muted)] text-[var(--accent)]">
            <UserCircle className="h-5 w-5" />
          </span>
          <div>
            <h1 className="text-base font-semibold tracking-tight text-slate-100">Meu perfil</h1>
            <p className="mt-0.5 text-xs text-[var(--muted)]">Gerencie suas informa+º+Áes pessoais</p>
          </div>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto p-6">
        <div className="mx-auto w-full max-w-2xl space-y-4">
          {/* Profile card with avatar */}
          <div className="rounded-xl border border-[var(--border)] bg-[var(--surface-1)] p-5">
            <div className="flex items-start justify-between">
              <div className="flex items-center gap-4">
                <div className="relative group">
                  <div className="flex h-16 w-16 shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-cyan-400 to-indigo-500 text-xl font-bold text-slate-950 overflow-hidden">
                    {avatarUrl ? (
                      <Image
                        src={avatarUrl}
                        alt="Avatar"
                        width={64}
                        height={64}
                        className="h-full w-full object-cover"
                      />
                    ) : (
                      user.username[0].toUpperCase()
                    )}
                  </div>
                  <label
                    className="absolute inset-0 flex items-center justify-center rounded-full bg-black/50 opacity-0 transition group-hover:opacity-100 cursor-pointer"
                    title="Alterar foto"
                  >
                    <Camera className="h-5 w-5 text-white" />
                    <input
                      ref={fileInputRef}
                      type="file"
                      accept="image/png,image/jpeg,image/webp,image/avif,image/gif"
                      className="hidden"
                      onChange={handleAvatarChange}
                    />
                  </label>
                  {avatarUrl && (
                    <button
                      type="button"
                      onClick={removeAvatar}
                      className="absolute -top-1 -right-1 flex h-5 w-5 items-center justify-center rounded-full bg-rose-500 text-white opacity-0 transition group-hover:opacity-100"
                      title="Remover foto"
                    >
                      <X className="h-3 w-3" />
                    </button>
                  )}
                </div>
                <div>
                  <h2 className="text-base font-semibold text-slate-100">{user.username}</h2>
                  <p className="text-sm text-[var(--muted)]">{user.email}</p>
                  <p className="mt-1 text-xs text-[var(--muted-fg)]">
                    Entrou em {new Date(user.created_at).toLocaleDateString("pt-BR")}
                  </p>
                </div>
              </div>
              <button
                type="button"
                onClick={() => {
                  setEditing((v) => !v);
                  setError(null);
                  setSuccess(false);
                }}
                className={`inline-flex items-center gap-1.5 rounded-lg border px-3 py-2 text-xs font-medium transition ${
                  editing
                    ? "border-[var(--accent)]/30 bg-[var(--accent-muted)] text-indigo-200"
                    : "border-[var(--border)] text-[var(--muted-fg)] hover:border-slate-500 hover:text-slate-200"
                }`}
              >
                <Pencil className="h-3.5 w-3.5" />
                {editing ? "Cancelar" : "Editar"}
              </button>
            </div>

            {editing && (
              <div className="mt-5 space-y-3">
                <label className="block">
                  <span className="text-xs text-[var(--muted-fg)]">Nome de usu+írio</span>
                  <input
                    value={form.username}
                    onChange={(e) => setForm((f) => ({ ...f, username: e.target.value }))}
                    className="mt-1 w-full rounded-lg border border-[var(--border)] bg-black/30 px-3 py-2 text-sm text-slate-100 focus:outline-none focus:ring-2 focus:ring-[var(--accent)] focus:border-[var(--accent)]/40"
                  />
                </label>
                <label className="block">
                  <span className="text-xs text-[var(--muted-fg)]">E-mail</span>
                  <input
                    type="email"
                    value={form.email}
                    onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))}
                    className="mt-1 w-full rounded-lg border border-[var(--border)] bg-black/30 px-3 py-2 text-sm text-slate-100 focus:outline-none focus:ring-2 focus:ring-[var(--accent)] focus:border-[var(--accent)]/40"
                  />
                </label>
                <label className="block">
                  <span className="text-xs text-[var(--muted-fg)]">Telefone</span>
                  <input
                    value={form.phone}
                    onChange={(e) => {
                      const raw = e.target.value.replace(/\D/g, "");
                      const masked = maskPhone(raw);
                      setForm((f) => ({ ...f, phone: masked }));
                    }}
                    placeholder="+55 (xx) xxxxx-xxxx"
                    className="mt-1 w-full rounded-lg border border-[var(--border)] bg-black/30 px-3 py-2 text-sm text-slate-100 focus:outline-none focus:ring-2 focus:ring-[var(--accent)] focus:border-[var(--accent)]/40"
                  />
                </label>

                {/* Auto-save settings */}
                <div className="rounded-lg border border-[var(--border)] bg-black/20 p-3">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-sm font-medium text-slate-200">Salvamento autom+ítico</p>
                      <p className="text-xs text-[var(--muted)]">Salva seu progresso periodicamente</p>
                    </div>
                    <button
                      type="button"
                      onClick={() => setAutoSaveEnabled(!autoSaveEnabled)}
                      className={`relative inline-flex h-6 w-11 shrink-0 cursor-pointer rounded-full border-2 border-transparent transition ${
                        autoSaveEnabled ? "bg-[var(--accent)]" : "bg-[var(--surface-3)]"
                      }`}
                      aria-pressed={autoSaveEnabled}
                    >
                      <span
                        className={`pointer-events-none block h-5 w-5 rounded-full bg-white shadow transition-transform ${
                          autoSaveEnabled ? "translate-x-5" : "translate-x-0"
                        }`}
                      />
                    </button>
                  </div>
                  {autoSaveEnabled && (
                    <div className="mt-3 flex items-center gap-2">
                      <label className="text-xs text-[var(--muted)]">Intervalo (minutos):</label>
                      <input
                        type="number"
                        min={1}
                        max={60}
                        value={autoSaveInterval}
                        onChange={(e) => setAutoSaveInterval(parseInt(e.target.value) || 1)}
                        className="w-20 rounded-md border border-[var(--border)] bg-black/30 px-2 py-1 text-sm text-slate-100 focus:outline-none focus:ring-2 focus:ring-[var(--accent)]"
                      />
                    </div>
                  )}
                </div>

                <div className="flex items-center gap-3">
                  {error && <p className="text-xs text-rose-300">{error}</p>}
                  {success && <p className="text-xs text-emerald-300">Salvo com sucesso!</p>}
                </div>
                <div className="flex justify-end">
                  <button
                    type="button"
                    onClick={() => void save()}
                    disabled={saving}
                    className="inline-flex items-center gap-1.5 rounded-lg bg-[var(--accent)] px-4 py-2 text-sm font-medium text-slate-950 hover:bg-[var(--accent-hover)] disabled:opacity-50"
                  >
                    <Save className="h-3.5 w-3.5" />
                    {saving ? "SalvandoÔÇª" : "Salvar altera+º+Áes"}
                  </button>
                </div>
              </div>
            )}

            {!editing && (
              <dl className="mt-5 grid grid-cols-2 gap-x-6 gap-y-3 text-sm">
                <Field icon={<User className="h-4 w-4 text-[var(--muted)]" />} label="Usu+írio" value={user.username} />
                <Field icon={<Mail className="h-4 w-4 text-[var(--muted)]" />} label="E-mail" value={user.email} />
                <Field icon={<CalendarDays className="h-4 w-4 text-[var(--muted)]" />} label="Membro desde" value={new Date(user.created_at).toLocaleDateString("pt-BR")} />
                <Field icon={<Phone className="h-4 w-4 text-[var(--muted)]" />} label="Telefone" value={user.phone ?? "ÔÇö"} />
              </dl>
            )}
          </div>

          {/* Account info */}
          <div className="rounded-xl border border-[var(--border)] bg-[var(--surface-2)] p-5">
            <h3 className="inline-flex items-center gap-2 text-sm font-semibold text-slate-200">
              <IdCard className="h-4 w-4 text-[var(--accent)]" />
              Informa+º+Áes da conta
            </h3>
            <dl className="mt-3 grid grid-cols-2 gap-x-6 gap-y-3 text-sm">
              <Field icon={<BadgeCheck className="h-4 w-4 text-[var(--muted)]" />} label="ID do usu+írio" value={String(user.id)} />
              <Field icon={<Shield className="h-4 w-4 text-[var(--muted)]" />} label="Cargo" value={user.role ?? "ÔÇö"} />
              <Field icon={<Save className="h-4 w-4 text-[var(--muted)]" />} label="Salvamento autom+ítico" value={user.auto_save_enabled ? "Ativado" : "Desativado"} />
              <Field icon={<Timer className="h-4 w-4 text-[var(--muted)]" />} label="Intervalo de auto-save" value={`${user.auto_save_interval_minutes ?? 15} min`} />
            </dl>
          </div>

          {/* Danger zone */}
          <div className="rounded-xl border border-rose-500/20 bg-rose-500/5 p-5">
            <h3 className="inline-flex items-center gap-2 text-sm font-semibold text-rose-300">
              <AlertTriangle className="h-4 w-4" />
              Zona de perigo
            </h3>
            <p className="mt-1 text-xs text-rose-400/70">
              Excluir sua conta remove permanentemente todos os dados e projetos.
            </p>
            <p className="mt-3 text-xs text-[var(--muted)]">Contate o suporte para exclus+úo.</p>
          </div>
        </div>
      </main>

      {/* Crop Modal */}
      {showCrop && cropImage && (
        <CropModal
          src={cropImage}
          cropState={cropState}
          setCropState={setCropState}
          onApply={() => {
            // Save the current crop state to localStorage
            try {
              localStorage.setItem("archia-crop-state", JSON.stringify(cropState));
            } catch {
              // ignore
            }
            applyCrop();
          }}
          onCancel={skipCrop}
          cropping={cropping}
        />
      )}
    </div>
  );
}

function Field({ icon, label, value }: { icon?: React.ReactNode; label: string; value: string }) {
  return (
    <div className="flex items-start gap-3">
      {icon && <span className="mt-0.5">{icon}</span>}
      <div>
        <dt className="text-xs text-[var(--muted)]">{label}</dt>
        <dd className="mt-0.5 font-medium text-slate-200">{value}</dd>
      </div>
    </div>
  );
}

// ÔöÇÔöÇÔöÇ Crop Modal Component ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
function CropModal({
  src,
  cropState,
  setCropState,
  onApply,
  onCancel,
  cropping,
}: {
  src: string;
  cropState: CropState;
  setCropState: React.Dispatch<React.SetStateAction<CropState>>;
  onApply: () => void;
  onCancel: () => void;
  cropping: boolean;
}) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const dragStartRef = useRef<{ x: number; y: number; state: CropState }>({ x: 0, y: 0, state: { x: 0, y: 0, width: 0, height: 0 } });
  const dragTypeRef = useRef<string | null>(null);

  function onMouseDown(e: React.MouseEvent, type: string) {
    e.preventDefault();
    e.stopPropagation();
    dragTypeRef.current = type;
    dragStartRef.current = {
      x: e.clientX,
      y: e.clientY,
      state: { ...cropState },
    };
    setIsDragging(true);
  }

  useEffect(() => {
    function onMouseMove(e: MouseEvent) {
      if (!isDragging) return;

      const rect = containerRef.current?.getBoundingClientRect();
      if (!rect) return;

      const dx = ((e.clientX - dragStartRef.current.x) / rect.width) * 100;
      const dy = ((e.clientY - dragStartRef.current.y) / rect.height) * 100;
      const base = dragStartRef.current.state;
      const type = dragTypeRef.current;

      if (type === "move") {
        const newX = Math.max(0, Math.min(100 - base.width, base.x + dx));
        const newY = Math.max(0, Math.min(100 - base.height, base.y + dy));
        setCropState({ ...base, x: newX, y: newY });
      } else if (type === "br") {
        // Bottom-right: only change size, keep top-left fixed
        const newW = Math.max(10, Math.min(100 - base.x, base.width + dx));
        const newH = Math.max(10, Math.min(100 - base.y, base.height + dy));
        setCropState({ ...base, width: newW, height: newH });
      } else if (type === "tl") {
        // Top-left: only change size, keep bottom-right fixed
        const newW = Math.max(10, base.width - dx);
        const newH = Math.max(10, base.height - dy);
        const newX = Math.max(0, base.x + dx);
        const newY = Math.max(0, base.y + dy);
        setCropState({ x: newX, y: newY, width: newW, height: newH });
      } else if (type === "tr") {
        // Top-right: only change size, keep bottom-left fixed
        const newW = Math.max(10, Math.min(100 - base.x, base.width + dx));
        const newH = Math.max(10, base.height - dy);
        const newY = Math.max(0, base.y + dy);
        setCropState({ ...base, y: newY, width: newW, height: newH });
      } else if (type === "bl") {
        // Bottom-left: only change size, keep top-right fixed
        const newW = Math.max(10, base.width - dx);
        const newH = Math.max(10, Math.min(100 - base.y, base.height + dy));
        const newX = Math.max(0, base.x + dx);
        setCropState({ ...base, x: newX, width: newW, height: newH });
      }
    }

    function onMouseUp() {
      setIsDragging(false);
      dragTypeRef.current = null;
    }

    if (isDragging) {
      window.addEventListener("mousemove", onMouseMove);
      window.addEventListener("mouseup", onMouseUp);
    }
    return () => {
      window.removeEventListener("mousemove", onMouseMove);
      window.removeEventListener("mouseup", onMouseUp);
    };
  }, [isDragging, cropState, setCropState]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 p-4 backdrop-blur-sm">
      <div className="w-full max-w-lg rounded-2xl border border-[var(--border)] bg-[var(--surface-2)] p-5">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-base font-semibold text-slate-100 flex items-center gap-2">
            <Crop className="h-5 w-5 text-[var(--accent)]" />
            Ajustar foto de perfil
          </h3>
          <button
            type="button"
            onClick={onCancel}
            className="rounded-lg p-2 text-[var(--muted-fg)] hover:bg-white/5 hover:text-[var(--foreground)]"
            aria-label="Fechar"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* Image container with crop overlay */}
        <div
          ref={containerRef}
          className="relative w-full aspect-square overflow-hidden rounded-lg bg-[var(--surface-3)] select-none"
        >
          <Image
            src={src}
            alt="Crop preview"
            width={500}
            height={500}
            className="h-full w-full object-cover"
          />
          {/* Dark overlay outside crop area */}
          <div className="absolute inset-0 pointer-events-none">
            {/* Top */}
            <div
              className="absolute left-0 right-0 bg-black/60"
              style={{ top: 0, height: `${cropState.y}%` }}
            />
            {/* Bottom */}
            <div
              className="absolute left-0 right-0 bg-black/60"
              style={{ top: `${cropState.y + cropState.height}%`, height: `${100 - cropState.y - cropState.height}%` }}
            />
            {/* Left - only in crop vertical range */}
            <div
              className="absolute top-0 bottom-0 bg-black/60"
              style={{ left: 0, width: `${cropState.x}%` }}
            />
            {/* Right - only in crop vertical range */}
            <div
              className="absolute top-0 bottom-0 bg-black/60"
              style={{ right: 0, width: `${100 - cropState.x - cropState.width}%` }}
            />
          </div>
          {/* Crop area */}
          <div
            className="absolute border-2 border-[var(--accent)] shadow-lg cursor-move"
            style={{
              left: `${cropState.x}%`,
              top: `${cropState.y}%`,
              width: `${cropState.width}%`,
              height: `${cropState.height}%`,
            }}
            onMouseDown={(e) => onMouseDown(e, "move")}
          >
            {/* Grid lines (thirds) */}
            <div className="absolute inset-0 pointer-events-none">
              <div className="absolute left-1/3 top-0 bottom-0 w-px bg-white/30" />
              <div className="absolute left-2/3 top-0 bottom-0 w-px bg-white/30" />
              <div className="absolute top-1/3 left-0 right-0 h-px bg-white/30" />
              <div className="absolute top-2/3 left-0 right-0 h-px bg-white/30" />
            </div>
            {/* Corner handles */}
            <div
              className="absolute -top-1.5 -left-1.5 w-3 h-3 bg-[var(--accent)] rounded-full cursor-nwse-resize"
              onMouseDown={(e) => { e.stopPropagation(); onMouseDown(e, "tl"); }}
            />
            <div
              className="absolute -top-1.5 -right-1.5 w-3 h-3 bg-[var(--accent)] rounded-full cursor-nesw-resize"
              onMouseDown={(e) => { e.stopPropagation(); onMouseDown(e, "tr"); }}
            />
            <div
              className="absolute -bottom-1.5 -left-1.5 w-3 h-3 bg-[var(--accent)] rounded-full cursor-nesw-resize"
              onMouseDown={(e) => { e.stopPropagation(); onMouseDown(e, "bl"); }}
            />
            <div
              className="absolute -bottom-1.5 -right-1.5 w-3 h-3 bg-[var(--accent)] rounded-full cursor-nwse-resize"
              onMouseDown={(e) => { e.stopPropagation(); onMouseDown(e, "br"); }}
            />
          </div>
        </div>

        <p className="mt-3 text-xs text-[var(--muted)] text-center">
          Arraste o quadrado para posicionar ÔÇó Arraste os cantos para ajustar o tamanho
        </p>

        <div className="mt-5 flex justify-end gap-2">
          <button
            type="button"
            onClick={onCancel}
            className="rounded-lg px-3 py-2 text-sm text-[var(--muted-fg)] hover:bg-white/5"
          >
            Cancelar
          </button>
          <button
            type="button"
            onClick={onApply}
            disabled={cropping}
            className="inline-flex items-center gap-1.5 rounded-lg bg-[var(--accent)] px-4 py-2 text-sm font-medium text-[var(--accent-fg)] hover:bg-[var(--accent-hover)] disabled:opacity-50"
          >
            {cropping ? (
              <span className="h-4 w-4 animate-spin rounded-full border-2 border-current border-t-transparent" />
            ) : (
              <CheckCircle2 className="h-4 w-4" />
            )}
            {cropping ? "ProcessandoÔÇª" : "Aplicar"}
          </button>
        </div>
      </div>
    </div>
  );
}

