            x: Math.max(16, position.x - abs.x - 100),
            y: Math.max(56, position.y - abs.y - 30),
          },
          container.id,
        );
        return;
      }

      addCatalogNode(catalogId, { x: position.x - 100, y: position.y - 30 });
