"use client";

/**
 * Diagrama Livre = Excalidraw oficial, sem chrome Archia.
 * API m+¡nima da lib ÔÇö igual ao exemplo dos docs.
 */
import "@excalidraw/excalidraw/index.css";
import { Excalidraw } from "@excalidraw/excalidraw";
import type { ExcalidrawElement } from "@excalidraw/excalidraw/element/types";
import { useGraphStore } from "@/lib/graph-store";
import { useCallback, useEffect, useRef, useState } from "react";

function elementsFingerprint(elements: readonly ExcalidrawElement[]): string {
  let h = 2166136261;
  const mix = (s: string) => {
    for (let i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
  };
  mix(String(elements.length));
  for (const el of elements) {
    mix(el.id);
    mix(el.type);
    mix(String(el.version ?? 0));
    mix(String(el.versionNonce ?? 0));
    mix(String(el.isDeleted ? 1 : 0));
    mix(String(Math.round(el.x)));
    mix(String(Math.round(el.y)));
    mix(String(Math.round(el.width)));
    mix(String(Math.round(el.height)));
    mix(String(el.updated ?? 0));
  }
  return (h >>> 0).toString(36);
}

function hideSocialLinks() {
  // Hide "Excalidraw links" section and social items
  document.querySelectorAll<HTMLElement>('[class*="dropdown-menu-group"]').forEach((group) => {
    const title = group.querySelector<HTMLElement>('[class*="dropdown-menu-group-title"]');
    if (title && title.textContent?.includes("Excalidraw")) {
      group.style.display = "none";
    }
  });
  document.querySelectorAll<HTMLElement>('[aria-label="GitHub"], [title="GitHub"], [aria-label="Discord"], [title="Discord"]').forEach((el) => {
    if (el.parentElement) el.parentElement.style.display = "none";
  });
  document.querySelectorAll<HTMLElement>('[class*="dropdown-menu-item"]').forEach((item) => {
    const text = item.textContent?.trim() || "";
    if (text === "GitHub" || text === "Discord" || text === "Follow us") {
      item.style.display = "none";
    }
  });
}

export default function ExcalidrawWrapper() {
  const elements = useGraphStore((s) => s.excalidrawElements ?? []);
  const setElements = useGraphStore((s) => s.setExcalidrawElements);
  const lastFpRef = useRef(elementsFingerprint(elements));
  const containerRef = useRef<HTMLDivElement>(null);
  const [ready, setReady] = useState(false);

  const initialDataRef = useRef({
    elements: elements as ExcalidrawElement[],
  });

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const check = () => {
      const { width, height } = el.getBoundingClientRect();
      if (width > 0 && height > 0) {
        setReady(true);
        return true;
      }
      return false;
    };
    if (check()) return;
    const ro = new ResizeObserver(() => {
      if (check()) ro.disconnect();
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  const onChange = useCallback(
    (next: readonly ExcalidrawElement[]) => {
      const fp = elementsFingerprint(next);
      if (fp === lastFpRef.current) return;
      lastFpRef.current = fp;
      setElements([...next]);
    },
    [setElements],
  );

  // Hide social links when menu opens
  useEffect(() => {
    const observer = new MutationObserver(() => {
      setTimeout(hideSocialLinks, 50);
    });
    observer.observe(document.body, { childList: true, subtree: true });
    hideSocialLinks();
    return () => observer.disconnect();
  }, []);

  return (
    <div
      ref={containerRef}
      data-testid="excalidraw-container"
      style={{ height: "100%", width: "100%" }}
    >
      {ready ? (
        <Excalidraw
          initialData={initialDataRef.current}
          onChange={onChange}
          langCode="pt-BR"
          theme="light"
        />
      ) : null}
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import { findGlossaryTerm, type GlossaryTerm } from "@/lib/glossary";

interface Props {
  nodeId: string;
  nodeLabel: string;
  nodeTech?: string;
  children: React.ReactNode;
}

/**
 * P3.1.3 ÔÇö Tooltip de gloss+írio ao hover em n+¦s do canvas.
 */
export default function NodeGlossaryTooltip({ nodeId, nodeLabel, nodeTech, children }: Props) {
  const [show, setShow] = useState(false);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const term = useMemo(() => findGlossaryTerm(nodeId) ?? findGlossaryTerm(nodeLabel), [nodeId, nodeLabel]);

  if (!term) {
    return <>{children}</>;
  }

  const handleMouseEnter = (e: React.MouseEvent) => {
    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
    setPosition({ x: rect.right + 8, y: rect.top });
    setShow(true);
  };

  const handleMouseLeave = () => setShow(false);

  return (
    <>
      <div onMouseEnter={handleMouseEnter} onMouseLeave={handleMouseLeave} style={{ display: "inline-block" }}>
        {children}
      </div>
      {show && (
        <div
          className="fixed z-50 w-72 rounded-lg border border-[var(--border-strong)] bg-[var(--surface-1)]/95 p-3 text-xs text-slate-200 elev-4 backdrop-blur"
          style={{ left: Math.min(position.x, window.innerWidth - 300), top: position.y }}
          role="tooltip"
          aria-label={`Gloss+írio: ${term.term}`}
        >
          <div className="flex items-start justify-between">
            <p className="font-semibold text-indigo-300">{term.term}</p>
            <span className="rounded bg-white/10 px-2 py-0.5 text-sm text-[var(--muted-fg)]">
              {term.category}
            </span>
          </div>
          <p className="mt-2 text-slate-300">{term.definition}</p>
          {term.related && term.related.length > 0 && (
            <div className="mt-2 flex flex-wrap gap-2">
              {term.related.map((r) => (
                <span key={r} className="rounded bg-violet-500/20 px-2 py-0.5 text-sm text-violet-200">
                  {r}
                </span>
              ))}
            </div>
          )}
        </div>
      )}
    </>
  );
}

