            rows={8}
            value={text}
            onChange={e => setText(e.target.value)}
            placeholder="Cole aqui a descri+º+úo do seu diagrama...

Exemplo:
1. Roteiro pronto
2. Tratamento com IA
3. Eleven labs (+íudio)
4. Hey gen (v+¡deo)
5. Est+¦dio"
          />
        </div>
        <div className="mb-2 flex gap-2">
          <button
            onClick={handleGenerate}
            disabled={loading || !text.trim()}
