"use client";

import { useEffect, useId, useState } from "react";
import {
  downloadJson,
  downloadText,
  slugifyFilename,
  toArchitectureMarkdown,
  toExportPayload,
} from "@/lib/export";
import { exportArchitecturePdf, exportArchitecturePng, type CaptureCanvasOptions } from "@/lib/export-canvas";
import { downloadSvg, renderSvg } from "@/lib/export-svg";
import { useGraphStore } from "@/lib/graph-store";

export type ExportFormat = "png" | "svg" | "pdf" | "json" | "md";

export type ExportOptions = {
  format: ExportFormat;
  margin: number;
  width: number;
  height: number;
  pixelRatio: number;
  boardReady: boolean;
};

type Props = {
  open: boolean;
  onClose: () => void;
  initialFormat?: ExportFormat;
};

const DEFAULTS: ExportOptions = {
  format: "png",
  margin: 0.15,
  width: 1600,
  height: 900,
  pixelRatio: 2,
  boardReady: true,
};

export default function ExportOptionsModal({ open, onClose, initialFormat = "png" }: Props) {
  const titleId = useId();
  const [opts, setOpts] = useState<ExportOptions>({ ...DEFAULTS, format: initialFormat });
  const [busy, setBusy] = useState(false);

  const name = useGraphStore((s) => s.name);
  const context = useGraphStore((s) => s.context);
  const nfr = useGraphStore((s) => s.nfr);
  const nodes = useGraphStore((s) => s.nodes);
  const edges = useGraphStore((s) => s.edges);
  const analysis = useGraphStore((s) => s.analysis);
  const pushUiNotice = useGraphStore((s) => s.pushUiNotice);

  useEffect(() => {
    if (open) setOpts((o) => ({ ...o, format: initialFormat }));
  }, [open, initialFormat]);

  if (!open) return null;

  const base = slugifyFilename(name);

  async function run() {
    setBusy(true);
    try {
      const capture: CaptureCanvasOptions = {
        width: opts.width,
        height: opts.height,
        padding: opts.margin,
        pixelRatio: opts.pixelRatio,
        boardReady: opts.boardReady,
        meta: {
          title: name,
          nfr,
          author: "Arquiteto",
          version: "1.0",
        },
      };

      if (opts.format === "png") {
        await exportArchitecturePng(`${base}.png`, nodes, {
          boardReady: opts.boardReady,
          meta: capture.meta,
          width: opts.width,
          height: opts.height,
          padding: opts.margin,
          pixelRatio: opts.pixelRatio,
        });
        pushUiNotice({ type: "success", text: "PNG exportado com as op+º+Áes escolhidas." });
      } else if (opts.format === "svg") {
        const svg = renderSvg(nodes, edges, { title: name });
        downloadSvg(svg, `${base}.svg`);
        pushUiNotice({ type: "success", text: "SVG exportado." });
      } else if (opts.format === "pdf") {
        await exportArchitecturePdf(name, nodes, edges, {
          context,
          nfr,
          analysis,
          includeDiagram: true,
          meta: capture.meta,
        });
        pushUiNotice({ type: "success", text: "PDF: use ÔÇ£Salvar como PDFÔÇØ na impress+úo." });
      } else if (opts.format === "json") {
        downloadJson(
          `${base}.graph.json`,
          await toExportPayload(name, nodes, edges, analysis, context, nfr),
        );
        pushUiNotice({ type: "success", text: "JSON exportado." });
      } else {
        const md = toArchitectureMarkdown(name, nodes, edges, { context, nfr, analysis });
        downloadText(`${base}.architecture-package.md`, md, "text/markdown;charset=utf-8");
        pushUiNotice({ type: "success", text: "Markdown exportado." });
      }
      onClose();
    } catch (err) {
      pushUiNotice({
        type: "error",
        text: err instanceof Error ? err.message : "Falha na exporta+º+úo.",
      });
    } finally {
      setBusy(false);
    }
  }

  return (
    <div
      className="fixed inset-0 z-[80] flex items-center justify-center bg-black/60 p-4"
      role="dialog"
      aria-modal="true"
      aria-labelledby={titleId}
      onClick={onClose}
    >
      <div
        className="w-full max-w-md rounded-2xl border border-[var(--border-strong)] bg-[var(--surface-1)] p-5 elev-4"
        onClick={(e) => e.stopPropagation()}
      >
        <h2 id={titleId} className="text-base font-semibold text-[var(--foreground)]">
          Op+º+Áes de exporta+º+úo
        </h2>
        <p className="mt-1 text-sm text-[var(--muted)]">
          Ajuste formato, margem, resolu+º+úo e title block.
        </p>

        <div className="mt-4 space-y-3">
          <label className="block text-sm">
            <span className="text-[var(--muted)]">Formato</span>
            <select
              className="mt-1 w-full rounded-lg border border-[var(--border)] bg-[var(--surface-2)] px-3 py-2 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent)]"
              value={opts.format}
              onChange={(e) => setOpts({ ...opts, format: e.target.value as ExportFormat })}
            >
              <option value="png">PNG</option>
              <option value="svg">SVG</option>
              <option value="pdf">PDF</option>
              <option value="json">JSON</option>
              <option value="md">Markdown</option>
            </select>
          </label>

          {(opts.format === "png" || opts.format === "pdf") && (
            <>
              <label className="block text-sm">
                <span className="text-[var(--muted)]">Margem (padding 0ÔÇô0.4)</span>
                <input
                  type="number"
                  min={0}
                  max={0.4}
                  step={0.05}
                  className="mt-1 w-full rounded-lg border border-[var(--border)] bg-[var(--surface-2)] px-3 py-2 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent)]"
                  value={opts.margin}
                  onChange={(e) => setOpts({ ...opts, margin: Number(e.target.value) || 0 })}
                />
              </label>
              <div className="grid grid-cols-2 gap-2">
                <label className="block text-sm">
                  <span className="text-[var(--muted)]">Largura</span>
                  <input
                    type="number"
                    min={640}
                    max={4096}
                    className="mt-1 w-full rounded-lg border border-[var(--border)] bg-[var(--surface-2)] px-3 py-2 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent)]"
                    value={opts.width}
                    onChange={(e) => setOpts({ ...opts, width: Number(e.target.value) || 1600 })}
                  />
                </label>
                <label className="block text-sm">
                  <span className="text-[var(--muted)]">Altura</span>
                  <input
                    type="number"
                    min={480}
                    max={4096}
                    className="mt-1 w-full rounded-lg border border-[var(--border)] bg-[var(--surface-2)] px-3 py-2 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent)]"
                    value={opts.height}
                    onChange={(e) => setOpts({ ...opts, height: Number(e.target.value) || 900 })}
                  />
                </label>
              </div>
              <label className="block text-sm">
                <span className="text-[var(--muted)]">Pixel ratio (1ÔÇô3)</span>
                <input
                  type="number"
                  min={1}
                  max={3}
                  step={0.5}
                  className="mt-1 w-full rounded-lg border border-[var(--border)] bg-[var(--surface-2)] px-3 py-2 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent)]"
                  value={opts.pixelRatio}
                  onChange={(e) => setOpts({ ...opts, pixelRatio: Number(e.target.value) || 2 })}
                />
              </label>
              <label className="flex items-center gap-2 text-sm text-[var(--foreground)]">
                <input
                  type="checkbox"
                  checked={opts.boardReady}
                  onChange={(e) => setOpts({ ...opts, boardReady: e.target.checked })}
                />
                Board-ready (title block + legenda)
              </label>
            </>
          )}
        </div>

        <div className="mt-5 flex justify-end gap-2">
          <button type="button" className="btn-ghost" onClick={onClose} disabled={busy}>
            Cancelar
          </button>
          <button
            type="button"
            className="btn-primary"
            onClick={() => void run()}
            disabled={busy}
            data-testid="export-options-confirm"
          >
            {busy ? "ExportandoÔÇª" : "Exportar"}
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { Moon, Play, SkipBack, SkipForward, Sun, X } from "lucide-react";
import { useGraphStore } from "@/lib/graph-store";

interface Props {
  graphId: string;
}

type Theme = "dark" | "light";

/** P0.2.9 ÔÇö Presentation mode: spotlight + teclas + fundo claro opcional. */
export default function PresentationMode({ graphId: _graphId }: Props) {
  const setHighlightNodeIds = useGraphStore((s) => s.setHighlightNodeIds);
  const setDiffHighlights = useGraphStore((s) => s.setDiffHighlights);
  const edges = useGraphStore((s) => s.edges);
  const [step, setStep] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [open, setOpen] = useState(false);
  const [theme, setTheme] = useState<Theme>("dark");
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const steps = edges
    .filter((e) => e.data?.flowNumber != null)
    .map((e) => ({
      id: e.id,
      flowNumber: Number(e.data?.flowNumber),
      label: String(e.data?.label ?? e.id),
      source: e.source,
      target: e.target,
    }))
    .sort((a, b) => a.flowNumber - b.flowNumber);

  const handlePrev = () => setStep((s) => Math.max(0, s - 1));
  const handleNext = () => setStep((s) => Math.min(steps.length - 1, s + 1));
  const handlePlay = () => setPlaying((v) => !v);

  // Update highlights when step changes
  useEffect(() => {
    if (steps.length === 0) {
      setHighlightNodeIds([]);
      setDiffHighlights([]);
      return;
    }

    const highlightedNodes = new Set<string>();
    const highlightedEdges = new Set<string>();

    for (let i = 0; i <= Math.min(step, steps.length - 1); i++) {
      highlightedEdges.add(steps[i].id);
      highlightedNodes.add(steps[i].source);
      highlightedNodes.add(steps[i].target);
    }

    setHighlightNodeIds(Array.from(highlightedNodes));
    setDiffHighlights(
      Array.from(highlightedEdges).map((id) => ({
        edgeId: id,
        status: "added",
      })),
    );
  }, [step, steps, setHighlightNodeIds, setDiffHighlights]);

  // Keyboard nav: ArrowLeft/Right, Space (play/pause), Escape (close)
  useEffect(() => {
    if (!open) return;
    function onKeyDown(e: KeyboardEvent) {
      if (e.key === "ArrowRight" || e.key === " ") {
        e.preventDefault();
        if (e.key === " ") {
          setPlaying((v) => !v);
        } else {
          handleNext();
        }
      } else if (e.key === "ArrowLeft") {
        e.preventDefault();
        handlePrev();
      } else if (e.key === "Escape") {
        setOpen(false);
      } else if (e.key === "t" || e.key === "T") {
        setTheme((v) => (v === "dark" ? "light" : "dark"));
      }
    }
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [open, step, steps.length]);

  // Auto-play interval
  useEffect(() => {
    if (!playing || steps.length === 0) {
      if (intervalRef.current) clearInterval(intervalRef.current);
      return;
    }
    intervalRef.current = setInterval(() => {
      setStep((s) => {
        if (s >= steps.length - 1) {
          if (intervalRef.current) clearInterval(intervalRef.current);
          setPlaying(false);
          return s;
        }
        return s + 1;
      });
    }, 3000);
    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, [playing, steps.length]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
      setHighlightNodeIds([]);
      setDiffHighlights([]);
    };
  }, [setHighlightNodeIds, setDiffHighlights]);

  // Apply light background when in light theme
  useEffect(() => {
    const body = document.body;
    if (theme === "light") {
      body.classList.add("archia-presentation-light");
    } else {
      body.classList.remove("archia-presentation-light");
    }
  }, [theme]);

  const current = steps[step] ?? steps[0];

  if (steps.length === 0) {
    return null;
  }

  if (!open) {
    return (
      <button
        type="button"
        className="fixed bottom-20 right-4 z-40 rounded-full bg-violet-600/80 p-2 text-white elev-2 hover:bg-violet-500"
        onClick={() => setOpen(true)}
        title="Modo apresenta+º+úo (Setas/T/Esc)"
        aria-label="Abrir modo apresenta+º+úo"
      >
        <Play size={16} />
      </button>
    );
  }

  return (
    <>
      {/* Controls */}
      <div
        className="fixed bottom-4 left-1/2 z-50 -translate-x-1/2 rounded-xl border border-[var(--border-strong)] bg-[var(--surface-1)]/95 px-4 py-3 elev-4 backdrop-blur"
        role="region"
        aria-label="Controles de apresenta+º+úo"
      >
        <div className="flex items-center gap-3">
          <button
            type="button"
            className="rounded-lg border border-[var(--border)] px-2 py-1 text-xs text-slate-300 hover:bg-white/10 disabled:opacity-50"
            onClick={handlePrev}
            disabled={step === 0}
            aria-label="Passo anterior"
          >
            <SkipBack size={14} />
          </button>
          <div className="flex flex-col items-center">
            <span className="text-xs font-semibold text-violet-300">
              Passo {step + 1} / {steps.length}
            </span>
            <span className="text-sm text-[var(--muted)]">
              {current?.label ?? steps[step]?.id}
            </span>
          </div>
          <button
            type="button"
            className="rounded-lg border border-[var(--border)] px-2 py-1 text-xs text-slate-300 hover:bg-white/10 disabled:opacity-50"
            onClick={handleNext}
            disabled={step >= steps.length - 1}
            aria-label="Pr+¦ximo passo"
          >
            <SkipForward size={14} />
          </button>
          <button
            type="button"
            className={`rounded-lg px-2 py-1 text-xs ${playing ? "bg-rose-500/20 text-rose-300" : "bg-emerald-500/20 text-emerald-300"}`}
            onClick={handlePlay}
            aria-label={playing ? "Pausar apresenta+º+úo" : "Iniciar apresenta+º+úo"}
          >
            {playing ? "Pausar" : "Auto"}
          </button>
          <button
            type="button"
            className="rounded-lg border border-[var(--border)] px-2 py-1 text-xs text-[var(--muted-fg)] hover:text-slate-200"
            onClick={() => setTheme((v) => (v === "dark" ? "light" : "dark"))}
            aria-label="Alternar tema"
            title="Tema claro/escuro (tecla T)"
          >
            {theme === "light" ? <Sun size={14} /> : <Moon size={14} />}
          </button>
          <button
            type="button"
            className="rounded-lg border border-[var(--border)] px-2 py-1 text-xs text-[var(--muted-fg)] hover:text-slate-200"
            onClick={() => setOpen(false)}
            aria-label="Fechar modo apresenta+º+úo"
          >
            <X size={14} />
          </button>
        </div>
        <p className="mt-2 text-sm text-[var(--muted)]">
          ÔåÉ ÔåÆ navegar -À Espa+ºo auto -À T tema -À Esc sair
        </p>
      </div>
    </>
  );
}

