  const setArchitectureView = useGraphStore((s) => s.setArchitectureView);
  const ownerTeam = useGraphStore((s) => s.ownerTeam);
  const diagramKind = useGraphStore((s) => s.diagramKind);
  const parentGraphId = useGraphStore((s) => s.parentGraphId);
  const c4ParentNodeId = useGraphStore((s) => s.c4ParentNodeId);
  const applyAutoLayout = useGraphStore((s) => s.applyAutoLayout);
  const highlightCriticalPath = useGraphStore((s) => s.highlightCriticalPath);
  const setSequenceMode = useGraphStore((s) => s.setSequenceMode);
  const sequenceMode = useGraphStore((s) => s.sequenceMode);
  const isLocked = useGraphStore((s) => s.isLocked);
  const setIsLocked = useGraphStore((s) => s.setIsLocked);
  const lastEtag = useGraphStore((s) => s.lastEtag);
  const loadGraph = useGraphStore((s) => s.loadGraph);

  const user = useAuthStore((s) => s.user);
  const [isOnline, setIsOnline] = useState(
    typeof navigator !== "undefined" ? navigator.onLine : true,
  );
  const [syncStatus, setSyncStatus] = useState<"synced" | "saving" | "error" | "offline">("synced");

  useEffect(() => {
    function onDoc(e: MouseEvent) {
      if (moreRef.current && !moreRef.current.contains(e.target as Node)) setMoreOpen(false);
    }
    if (moreOpen) document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, [moreOpen]);

  useEffect(() => {
    const onOnline = () => setIsOnline(true);
    const onOffline = () => setIsOnline(false);
    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);
    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  useEffect(() => {
    let unsub: (() => void) | undefined;
    void import("@/hooks/useAutoSave").then(({ subscribeSyncStatus }) => {
      unsub = subscribeSyncStatus(setSyncStatus);
    });
    return () => unsub?.();
  }, []);

  async function save() {
    try {
      const payload = {
        name,
        context,
        nfr,
        nodes,
        edges,
        owner_team: ownerTeam || null,
        diagram_kind: diagramKind,
        parent_graph_id: parentGraphId,
        c4_parent_node_id: c4ParentNodeId,
      };
      const saved = graphId
        ? await api.updateGraph(graphId, payload, { ifMatch: lastEtag })
        : await api.createGraph(payload);
      markSaved(saved.id, saved.etag ?? null);
      pushUiNotice({ type: "success", text: "Arquitetura salva." });
    } catch (err) {
      if (err instanceof ApiConflictError && graphId) {
        const keepMine = await confirm({
          title: "Conflito de vers+úo",
          description:
            "Outra sess+úo alterou este diagrama desde o seu +¦ltimo carregamento.",
          consequences:
            "Escolha ÔÇ£Usar minha vers+úoÔÇØ para sobrescrever o servidor, ou ÔÇ£Carregar do servidorÔÇØ para descartar suas altera+º+Áes locais.",
          confirmLabel: "Usar minha vers+úo",
          cancelLabel: "Carregar do servidor",
        });
        if (keepMine) {
          try {
            const payload = {
              name,
              context,
              nfr,
              nodes,
              edges,
              owner_team: ownerTeam || null,
              diagram_kind: diagramKind,
              parent_graph_id: parentGraphId,
              c4_parent_node_id: c4ParentNodeId,
            };
            const saved = await api.updateGraph(graphId, payload, { force: true });
            markSaved(saved.id, saved.etag ?? null);
            pushUiNotice({ type: "success", text: "Sua vers+úo foi salva (sobrescrita)." });
          } catch (e2) {
            pushUiNotice({
              type: "error",
              text: e2 instanceof Error ? e2.message : "Falha ao sobrescrever.",
            });
          }
        } else {
          try {
            const remote = await api.getGraph(graphId);
            loadGraph(remote);
            pushUiNotice({ type: "info", text: "Vers+úo do servidor carregada." });
          } catch (e2) {
            pushUiNotice({
              type: "error",
              text: e2 instanceof Error ? e2.message : "Falha ao recarregar do servidor.",
            });
          }
        }
        return;
      }
      pushUiNotice({
        type: "error",
        text:
          err instanceof Error
            ? `${err.message}. Verifique a conex+úo e tente novamente.`
            : "Falha ao salvar o projeto. Verifique a conex+úo e tente novamente.",
      });
    }
  }

  async function handleNew() {
    const ok = await confirm({
      title: "Come+ºar do zero?",
      description: "Isso limpa o canvas atual e cria um desenho em branco.",
      consequences: dirty
        ? "H+í altera+º+Áes n+úo salvas. Elas ser+úo perdidas se voc+¬ n+úo exportar ou salvar antes."
        : "O desenho atual ser+í descartado da tela (vers+Áes j+í salvas no servidor permanecem).",
      confirmLabel: "Novo desenho",
      tone: "danger",
    });
    if (ok) {
      reset();
      pushUiNotice({ type: "info", text: "Canvas limpo ÔÇö descreva o contexto e arraste um bloco." });
    }
  }

  async function handleDelete() {
    if (!selectedNodeId) return;
    const ok = await confirm({
      title: "Remover sele+º+úo?",
      description: "O bloco ou card selecionado ser+í removido do canvas.",
      consequences: "Voc+¬ pode desfazer com Ctrl+Z em seguida.",
      confirmLabel: "Remover",
      tone: "danger",
    });
    if (ok) deleteSelected();
  }

  return (
    <>
      {dialog}
