                      }
                    })();
                  }}
                />
                <MenuItem
                  icon={<Upload size={14} />}
                  label="Importar JSON"
                  onClick={() => {
                    fileRef.current?.click();
                    setMoreOpen(false);
                  }}
                />
                <MenuItem
                  icon={<Trash2 size={14} />}
                  label="Remover sele+º+úo"
                  disabled={!selectedNodeId && selectedNodeIds.length === 0}
                  onClick={() => {
                    setMoreOpen(false);
                    void handleDelete();
                  }}
                />
                <MenuItem
                  icon={<FolderOpen size={14} />}
                  label="Arquiteturas salvas"
                  href="/graphs"
