                />
                <MenuItem
                  icon={<GitCompareArrows size={14} />}
                  label="Comparar desenhos"
                  href="/compare"
                  onClick={() => setMoreOpen(false)}
                />
                <MenuItem
                  icon={<FilePlus2 size={14} />}
                  label="Novo desenho"
                  onClick={() => {
                    setMoreOpen(false);
                    void handleNew();
                  }}
