        <input
          ref={fileRef}
          type="file"
          accept="application/json"
          className="hidden"
          onChange={async (event) => {
            const file = event.target.files?.[0];
            event.target.value = "";
            if (!file) return;
            try {
              const parsed = await parseImportPayload(JSON.parse(await file.text()));
              loadSnapshot(parsed.name, parsed.nodes, parsed.edges, parsed.analysis, parsed.context, parsed.nfr);
              pushUiNotice({ type: "success", text: "Arquitetura importada." });
            } catch (err) {
              pushUiNotice({
                type: "error",
                text:
                  err instanceof Error
                    ? `${err.message}. Verifique se o arquivo +® um JSON exportado pelo Archia.`
                    : "JSON inv+ílido. Use um arquivo exportado pelo Archia e tente novamente.",
