"use client";

import { useVirtualizer } from "@tanstack/react-virtual";
import { useRef, type ReactNode } from "react";

type Props<T> = {
  items: T[];
  estimateSize?: number;
  className?: string;
  maxHeight?: number;
  renderItem: (item: T, index: number) => ReactNode;
  getKey: (item: T, index: number) => string;
};

export default function VirtualList<T>({
  items,
  estimateSize = 64,
  className = "",
  maxHeight = 420,
  renderItem,
  getKey,
}: Props<T>) {
  const parentRef = useRef<HTMLDivElement>(null);
  const virtualizer = useVirtualizer({
    count: items.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => estimateSize,
    overscan: 6,
  });

  if (items.length <= 24) {
    return (
      <ul className={className}>
        {items.map((item, i) => (
          <li key={getKey(item, i)}>{renderItem(item, i)}</li>
        ))}
      </ul>
    );
  }

  return (
    <div ref={parentRef} className={`overflow-y-auto ${className}`} style={{ maxHeight }}>
      <ul className="relative w-full" style={{ height: virtualizer.getTotalSize() }}>
        {virtualizer.getVirtualItems().map((row) => {
          const item = items[row.index];
          return (
            <li
              key={getKey(item, row.index)}
              className="absolute top-0 left-0 w-full"
              style={{ height: row.size, transform: `translateY(${row.start}px)` }}
            >
              {renderItem(item, row.index)}
            </li>
          );
        })}
      </ul>
    </div>
  );
}

import { useEffect, useRef } from "react";
import { useGraphStore } from "@/lib/graph-store";
import { useAuthStore } from "@/lib/auth-store";
import { persistLocalDraft, type SyncStatus } from "@/lib/local-draft";

const LOCAL_DRAFT_INTERVAL_MS = 5_000;
const COMPRESSION_THRESHOLD = 50; // Compress payloads with > 50 nodes

type SyncListener = (status: SyncStatus) => void;
const syncListeners = new Set<SyncListener>();
let currentSyncStatus: SyncStatus = "synced";

export function getSyncStatus(): SyncStatus {
  return currentSyncStatus;
}

export function subscribeSyncStatus(listener: SyncListener): () => void {
  syncListeners.add(listener);
  listener(currentSyncStatus);
  return () => {
    syncListeners.delete(listener);
  };
}

function setSyncStatus(status: SyncStatus) {
  currentSyncStatus = status;
  for (const listener of syncListeners) {
    listener(status);
  }
}

/** Compress JSON payload using browser's native CompressionStream API */
async function compressPayload<T>(data: T): Promise<string> {
  const json = JSON.stringify(data);
  if (json.length < 1024) return json; // Don't compress small payloads

  try {
    const blob = new Blob([json]);
    const compressedBlob = await new Response(blob.stream().pipeThrough(new CompressionStream("gzip"))).blob();
    const buffer = await compressedBlob.arrayBuffer();
    // Convert to base64 for transmission
    return btoa(String.fromCharCode(...new Uint8Array(buffer)));
  } catch {
    // Fallback to uncompressed if compression fails
    return json;
  }
}

/** Decompress base64-encoded gzip payload */
async function decompressPayload(base64: string): Promise<string> {
  try {
    const binaryString = atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    const blob = new Blob([bytes]);
    const decompressedBlob = await new Response(blob.stream().pipeThrough(new DecompressionStream("gzip"))).blob();
    return await decompressedBlob.text();
  } catch {
    // Fallback to raw JSON if decompression fails
    return base64;
  }
}

export function useAutoSave() {
  const user = useAuthStore((s) => s.user);
  const graphId = useGraphStore((s) => s.graphId);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const localTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // Persist draft locally every 5s (independent of backend).
  useEffect(() => {
    if (localTimerRef.current) clearInterval(localTimerRef.current);
    localTimerRef.current = setInterval(() => {
      const state = useGraphStore.getState();
      if (!state.graphId || state.nodes.length === 0) return;
      void persistLocalDraft({
        id: state.graphId,
        graphId: state.graphId,
        name: state.name,
        context: state.context,
        nfr: state.nfr,
        nodes: state.nodes,
        edges: state.edges,
        analysis: state.analysis,
        savedAt: new Date().toISOString(),
      });
    }, LOCAL_DRAFT_INTERVAL_MS);
    return () => {
      if (localTimerRef.current) clearInterval(localTimerRef.current);
    };
  }, []);

  useEffect(() => {
    if (timerRef.current) clearInterval(timerRef.current);
    if (!user || !user.auto_save_enabled || !graphId) return;
    const intervalMin = user.auto_save_interval_minutes;
    if (!intervalMin || intervalMin <= 0) return;
    const ms = intervalMin * 60 * 1000;
    timerRef.current = setInterval(async () => {
      const state = useGraphStore.getState();
      if (!state.graphId) return;

      setSyncStatus("saving");
      const base = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:4410";
      const payload = {
        nodes: state.nodes,
        edges: state.edges,
      };
      // Compress payload if large enough
      const payloadJson = JSON.stringify(payload);
      const body = payloadJson.length > 1024
        ? await compressPayload(payload)
        : payloadJson;

      void fetch(`${base}/api/v1/graphs/${state.graphId}`, {
        method: "PUT",
        credentials: "include",
        headers: {
          "Content-Type": "application/json",
          ...(body !== payloadJson ? { "Content-Encoding": "gzip" } : {}),
          ...(state.lastEtag ? { "If-Match": state.lastEtag } : {}),
        },
        body,
      })
        .then(async (res) => {
          if (res.ok) {
            setSyncStatus("synced");
            const etag = res.headers.get("ETag");
            state.markSaved(state.graphId!, etag);
            return;
          }
          if (res.status === 409) {
            setSyncStatus("error");
            state.pushUiNotice({
              type: "error",
              text: "Conflito: o diagrama mudou em outra sess+úo. Abra Salvar para resolver (minha vs servidor).",
            });
            return;
          }
          setSyncStatus("error");
          const detail = await res.text().catch(() => "");
          state.pushUiNotice({
            type: "error",
            text: detail
              ? `Falha ao salvar automaticamente (${res.status}). Rascunho local mantido.`
              : "Falha ao salvar automaticamente. Verifique a conex+úo ÔÇö rascunho local mantido.",
          });
          void persistLocalDraft({
            id: state.graphId!,
            graphId: state.graphId!,
            name: state.name,
            context: state.context,
            nfr: state.nfr,
            nodes: state.nodes,
            edges: state.edges,
            analysis: state.analysis,
            savedAt: new Date().toISOString(),
          });
        })
        .catch(() => {
          setSyncStatus("offline");
          state.pushUiNotice({
            type: "error",
            text: "Offline ÔÇö n+úo foi poss+¡vel salvar no servidor. Rascunho salvo localmente.",
          });
          void persistLocalDraft({
            id: state.graphId!,
            graphId: state.graphId!,
            name: state.name,
            context: state.context,
            nfr: state.nfr,
            nodes: state.nodes,
            edges: state.edges,
            analysis: state.analysis,
            savedAt: new Date().toISOString(),
          });
        });
    }, ms);
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [user, graphId]);
}

/** P0.2.2 ÔÇö Auto-layout por zonas (Edge ÔåÆ Public ÔåÆ Private ÔåÆ Data). */

import type { Edge, Node } from "@xyflow/react";
import type { CanvasNodeData, ZoneKind } from "./types";
import { isZoneData } from "./types";
import { isSwimlaneNode } from "./swimlanes";
import { isZoneNode, zoneKindOf, ZONE_DEFAULT_SIZE } from "./zones";
import { swimlaneSize } from "./swimlanes";

const LANE_ORDER: ZoneKind[] = [
  "region",
  "vpc",
  "availability_zone",
  "subnet_public",
  "subnet_private",
  "layer",
  "plane",
  "security_boundary",
  "tgw",
  "nat_gateway",
];

const CARD_W = 220;
const CARD_H = 88;
const GAP = 24;
const PAD = 32;

function containerSize(node: Node<CanvasNodeData>): { width: number; height: number } {
  if (isZoneNode(node)) {
    const kind = zoneKindOf(node);
    return kind ? ZONE_DEFAULT_SIZE[kind] : { width: 520, height: 320 };
  }
  if (isSwimlaneNode(node)) return swimlaneSize(node);
  return {
    width: Number(node.width ?? (node.style as { width?: number })?.width ?? 420),
    height: Number(node.height ?? (node.style as { height?: number })?.height ?? 280),
  };
}

/** Organiza cards filhos dentro de cada cont+¬iner, zonas em colunas por tipo. */
export function autoLayoutByZones(
  nodes: Node<CanvasNodeData>[],
  _edges: Edge[],
): Node<CanvasNodeData>[] {
  const next = nodes.map((n) => ({ ...n, position: { ...n.position } }));
  const byId = new Map(next.map((n) => [n.id, n]));

  const zones = next.filter((n) => isZoneNode(n) || isSwimlaneNode(n));
  zones.sort((a, b) => {
    const za = isZoneNode(a) ? LANE_ORDER.indexOf(zoneKindOf(a) ?? "layer") : 99;
    const zb = isZoneNode(b) ? LANE_ORDER.indexOf(zoneKindOf(b) ?? "layer") : 99;
    return za - zb;
  });

  let colX = 40;
  for (const zone of zones) {
    if (!zone.parentId) {
      zone.position = { x: colX, y: 40 };
      colX += containerSize(zone).width + GAP;
    }
    const children = next.filter((n) => n.parentId === zone.id && !isZoneNode(n) && !isSwimlaneNode(n));
    let cx = PAD;
    let cy = PAD + 24;
    let rowH = 0;
    for (const child of children) {
      child.position = { x: cx, y: cy };
      cx += CARD_W + GAP;
      rowH = Math.max(rowH, CARD_H);
      const maxW = containerSize(zone).width - PAD * 2;
      if (cx + CARD_W > maxW) {
        cx = PAD;
        cy += rowH + GAP;
        rowH = 0;
      }
    }
    byId.set(zone.id, zone);
  }

  const orphans = next.filter((n) => !n.parentId && !isZoneNode(n) && !isSwimlaneNode(n));
  let ox = 40;
  for (const o of orphans) {
    o.position = { x: ox, y: 600 };
    ox += CARD_W + GAP;
  }

  return next;
}

/** P0.1.6 ÔÇö Consist+¬ncia cross-diagram entre vistas do pacote. */

import type { DiagramKind } from "./diagram-library";

export type DiagramSnapshot = {
  graphId: string;
  kind: DiagramKind | string | null;
  name: string;
  nodes: Array<{ id: string; data?: { label?: string; catalogId?: string; stableRef?: string } }>;
};

export type ConsistencyIssue = {
  severity: "warning" | "critical";
  stableRef: string;
  label: string;
  presentIn: string[];
  missingIn: string[];
  detail: string;
};

function stableRef(node: DiagramSnapshot["nodes"][0]): string {
  const d = node.data ?? {};
  return (d.stableRef || d.catalogId || d.label || node.id).toLowerCase().trim();
}

/** Compara servi+ºos entre diagramas do mesmo projeto. */
export function analyzeDiagramConsistency(snapshots: DiagramSnapshot[]): ConsistencyIssue[] {
  if (snapshots.length < 2) return [];

  const byRef = new Map<string, { label: string; graphs: Set<string> }>();
  for (const snap of snapshots) {
    for (const n of snap.nodes) {
      const ref = stableRef(n);
      if (!ref) continue;
      const entry = byRef.get(ref) ?? { label: n.data?.label ?? ref, graphs: new Set() };
      entry.graphs.add(snap.graphId);
      byRef.set(ref, entry);
    }
  }

  const allGraphIds = snapshots.map((s) => s.graphId);
  const issues: ConsistencyIssue[] = [];

  for (const [ref, { label, graphs }] of byRef.entries()) {
    if (graphs.size === allGraphIds.length) continue;
    const presentIn = snapshots.filter((s) => graphs.has(s.graphId)).map((s) => s.name);
    const missingIn = snapshots.filter((s) => !graphs.has(s.graphId)).map((s) => s.name);
    issues.push({
      severity: missingIn.length >= allGraphIds.length - 1 ? "critical" : "warning",
      stableRef: ref,
      label,
      presentIn,
      missingIn,
      detail: `-½${label}-+ aparece em ${presentIn.join(", ")} mas falta em ${missingIn.join(", ")}.`,
    });
  }

  return issues.sort((a, b) => (a.severity === "critical" ? -1 : 1));
}

/**
 * P3.2.2 ÔÇö Renderiza diagrama como SVG puro (sem React Flow).
 * Usado para embed em Notion/Confluence com tema claro.
 */
import type { Node, Edge } from "@xyflow/react";
import { isArchData, type CanvasNodeData } from "./types";

export type EmbedOptions = {
  theme?: "light" | "dark";
  width?: number;
  height?: number;
  showControls?: boolean;
  showBackground?: boolean;
};

export type SvgEmbedResult = {
  svg: string;
  width: number;
  height: number;
  iframeSnippet: string;
};

const NODE_WIDTH = 210;
const NODE_HEIGHT = 80;
const ZONE_PADDING = 20;

function getDefaultColor(kind: string): { bg: string; border: string; text: string } {
  const colors: Record<string, { bg: string; border: string; text: string }> = {
    backend: { bg: "#1e293b", border: "#3b82f6", text: "#e2e8f0" },
    frontend: { bg: "#1e293b", border: "#8b5cf6", text: "#e2e8f0" },
    database: { bg: "#1e293b", border: "#10b981", text: "#e2e8f0" },
    cloud: { bg: "#1e293b", border: "#f59e0b", text: "#e2e8f0" },
    identity: { bg: "#1e293b", border: "#ef4444", text: "#e2e8f0" },
    observability: { bg: "#1e293b", border: "#06b6d4", text: "#e2e8f0" },
    integration: { bg: "#1e293b", border: "#a855f7", text: "#e2e8f0" },
    security: { bg: "#1e293b", border: "#f43f5e", text: "#e2e8f0" },
    deploy: { bg: "#1e293b", border: "#22c55e", text: "#e2e8f0" },
    zone: { bg: "transparent", border: "#475569", text: "#94a3b8" },
  };
  return colors[kind] ?? colors.backend;
}

export function renderEmbedSvg(
  nodes: Node<CanvasNodeData>[],
  edges: Edge[],
  options: EmbedOptions = {},
): SvgEmbedResult {
  const { theme = "light", width = 1200, height = 800 } = options;
  const isLight = theme === "light";

  // Calculate bounds
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const node of nodes) {
    minX = Math.min(minX, node.position.x);
    minY = Math.min(minY, node.position.y);
    maxX = Math.max(maxX, node.position.x + (node.width ?? NODE_WIDTH));
    maxY = Math.max(maxY, node.position.y + (node.height ?? NODE_HEIGHT));
  }

  const padding = 40;
  const svgWidth = Math.max(width, maxX - minX + padding * 2);
  const svgHeight = Math.max(height, maxY - minY + padding * 2);

  // Build SVG
  let svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${svgWidth}" height="${svgHeight}" viewBox="0 0 ${svgWidth} ${svgHeight}">`;

  // Background
  svg += `<rect width="${svgWidth}" height="${svgHeight}" fill="${isLight ? "#f8fafc" : "#0f172a"}"/>`;

  // Draw edges first (behind nodes)
  for (const edge of edges) {
    const source = nodes.find((n) => n.id === edge.source);
    const target = nodes.find((n) => n.id === edge.target);
    if (!source || !target) continue;

    const sx = source.position.x + NODE_WIDTH / 2;
    const sy = source.position.y + NODE_HEIGHT / 2;
    const tx = target.position.x + NODE_WIDTH / 2;
    const ty = target.position.y + NODE_HEIGHT / 2;

    svg += `<line x1="${sx}" y1="${sy}" x2="${tx}" y2="${ty}" stroke="${isLight ? "#94a3b8" : "#475569"}" stroke-width="1.5" stroke-dasharray="4,2"/>`;

    // Arrow head
    const angle = Math.atan2(ty - sy, tx - sx);
    const arrowLen = 6;
    svg += `<polygon points="${tx},${ty} ${tx - arrowLen * Math.cos(angle - Math.PI / 6)},${ty - arrowLen * Math.sin(angle - Math.PI / 6)} ${tx - arrowLen * Math.cos(angle + Math.PI / 6)},${ty - arrowLen * Math.sin(angle + Math.PI / 6)}" fill="${isLight ? "#94a3b8" : "#475569"}"/>`;
  }

  // Draw nodes
  for (const node of nodes) {
    const data = node.data as CanvasNodeData;
    const x = node.position.x + padding;
    const y = node.position.y + padding;
    const w = node.width ?? NODE_WIDTH;
    const h = node.height ?? NODE_HEIGHT;

    const colors = getDefaultColor(data.kind);
    const fillColor = isLight
      ? colors.bg.replace("#", "") === "1e293b" ? "#ffffff" : colors.bg
      : colors.bg;

    svg += `<g transform="translate(${x}, ${y})">`;
    svg += `<rect width="${w}" height="${h}" rx="8" fill="${fillColor}" stroke="${colors.border}" stroke-width="1.5"/>`;

    // Icon placeholder
    svg += `<circle cx="24" cy="${h / 2}" r="12" fill="${colors.border}20"/>`;

    // Label
    svg += `<text x="${48}" y="${h / 2 - 6}" fill="${isLight ? "#1e293b" : "#f1f5f9"}" font-size="12" font-weight="600" font-family="system-ui, sans-serif">${data.label}</text>`;
    svg += `<text x="${48}" y="${h / 2 + 10}" fill="${isLight ? "#64748b" : "#94a3b8"}" font-size="10" font-family="system-ui, sans-serif">${isArchData(data) ? data.tech || data.kind : data.kind}</text>`;

    svg += `</g>`;
  }

  svg += `</svg>`;

  // Generate iframe snippet with live embed URL
  const iframeSnippet =
    `<iframe src="/embed?theme=${theme}" width="${svgWidth}" height="${svgHeight}" ` +
    `style="border:1px solid ${isLight ? "#e2e8f0" : "#1e293b"};border-radius:8px;" ` +
    `title="Archia diagram" loading="lazy"></iframe>`;

  return {
    svg,
    width: svgWidth,
    height: svgHeight,
    iframeSnippet,
  };
}

import type { Edge, Node } from "@xyflow/react";
import { isArchData, isBlockData, isZoneData, type CanvasNodeData } from "./types";

/** P1.5.4 ÔÇö C4-PlantUML export (Context/Container level). */
export function exportToC4Plantuml(
  nodes: Node<CanvasNodeData>[],
  edges: Edge[],
  title = "Architecture",
): string {
  const lines: string[] = [
    "@startuml",
    "!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Container.puml",
    "",
    `title ${title}`,
    "",
    "Person(user, \"User\", \"End user\")",
    "",
  ];

  const systems = nodes.filter((n) => isArchData(n.data) && n.data.kind === "frontend");
  const containers = nodes.filter(
    (n) => isArchData(n.data) && ["backend", "database", "integration"].includes(n.data.kind),
  );
  const zones = nodes.filter((n) => isZoneData(n.data));

  for (const z of zones) {
    if (!isZoneData(z.data)) continue;
    lines.push(`Boundary(${sanitize(z.id)}, "${escape(z.data.label)}", "${z.data.zoneKind}") {`);
  }

  for (const s of systems) {
    if (!isArchData(s.data)) continue;
    lines.push(`  System(${sanitize(s.id)}, "${escape(s.data.label)}", "${escape(s.data.tech)}")`);
  }

  for (const c of containers) {
    if (!isArchData(c.data)) continue;
    const kind = c.data.kind === "database" ? "ContainerDb" : "Container";
    lines.push(
      `  ${kind}(${sanitize(c.id)}, "${escape(c.data.label)}", "${escape(c.data.tech)}", "${c.data.kind}")`,
    );
  }

  for (const z of zones) {
    lines.push("}");
  }

  lines.push("");
  for (const e of edges) {
    const label = (e.data as { label?: string })?.label ?? "";
    lines.push(`Rel(${sanitize(e.source)}, ${sanitize(e.target)}, "${escape(label)}")`);
  }

  lines.push("", "@enduml");
  return lines.join("\n");
}

function sanitize(id: string): string {
  return id.replace(/[^a-zA-Z0-9_]/g, "_");
}

function escape(s: string): string {
  return s.replace(/"/g, '\\"');
}

/**
 * Export graph to Mermaid flowchart format.
 * See https://mermaid.js.org
 */

import type { Edge, Node } from "@xyflow/react";
import type { CanvasNodeData, ZoneNodeData } from "./types";
import { isZoneData, isArchData } from "./types";

export function exportToMermaid(nodes: Node<CanvasNodeData>[], edges: Edge[], projectName = "Architecture"): string {
  const lines: string[] = [];
  lines.push("flowchart TB");
  lines.push("    subgraph nodes [Nodes]");

  const nodeMap = new Map<string, string>();

  for (const node of nodes) {
    const data = node.data as CanvasNodeData;
    const mermaidId = `node_${node.id.replace(/-/g, "_")}`;
    nodeMap.set(node.id, mermaidId);

    if (isZoneData(data)) {
      const zoneData = data as ZoneNodeData;
      const zoneId = `zone_${zoneData.zoneKind}`;
      lines.push(`        subgraph ${zoneId} ["${data.label || node.id}"]`);
      lines.push(`            direction TB`);
      lines.push(`            classDef zone fill:#0f172a,stroke:#334155,color:#94a3b8`);
      lines.push(`            class ${zoneId} zone`);
      lines.push("        end");
    } else if (isArchData(data)) {
      const config = data.config || {};
      const tech = data.tech || "";
      const label = data.label || node.id;
      const displayName = tech ? `${label}<br/><sub>${tech}</sub>` : label;
      lines.push(`        ${mermaidId}["${displayName}"]`);
    }
  }

  lines.push("    end");

  for (const edge of edges) {
    const srcId = nodeMap.get(edge.source);
    const tgtId = nodeMap.get(edge.target);
    if (!srcId || !tgtId) continue;

    const data = edge.data || {};
    const label = data.label || "";
    const protocol = data.protocol ? `|${data.protocol}|` : "";
    const criticalClass = data.isCriticalPath ? " class critical" : "";
    const linkStyle = data.flowKind === "async" ? "-.-.-" : "--";

    if (label) {
      lines.push(`    ${srcId} ${linkStyle}${protocol} ${tgtId}${criticalClass} : "${label}"`);
    } else {
      lines.push(`    ${srcId} ${linkStyle}${protocol} ${tgtId}${criticalClass}`);
    }
  }

  lines.push("");
  lines.push("    classDef critical stroke:#f43f5e,stroke-width:2px,fill:#1e1b4b,color:#fda4af");
  lines.push("");

  return lines.join("\n");
}

/**
 * Export graph to PlantUML format.
 * See https://plantuml.com
 */

import type { Edge, Node } from "@xyflow/react";
import type { CanvasNodeData, ZoneNodeData } from "./types";
import { isZoneData, isArchData } from "./types";

export function exportToPlantuml(nodes: Node<CanvasNodeData>[], edges: Edge[], projectName = "Architecture"): string {
  const lines: string[] = [];
  lines.push(`@startuml ${projectName}`);
  lines.push('skinparam linetype ortho');
  lines.push('skinparam sequenceArrowThickness 1');
  lines.push('skinparam maxMessageSize 200');
  lines.push("");

  const nodeMap = new Map<string, string>();

  // Define nodes
  for (const node of nodes) {
    const data = node.data as CanvasNodeData;
    const plantumlId = `node_${node.id}`.replace(/-/g, "_");
    nodeMap.set(node.id, plantumlId);

    if (isZoneData(data)) {
      const zoneData = data as ZoneNodeData;
      lines.push(`package "${data.label || node.id}" as ${plantumlId} {`);
      lines.push(`  [${zoneData.zoneKind.toUpperCase()}]`);
      lines.push("}");
    } else if (isArchData(data)) {
      const config = data.config || {};
      const tech = data.tech || "";
      const label = data.label || node.id;
      const description = tech ? `\\n(${tech})` : "";
      lines.push(`[${label}${description}] as ${plantumlId}`);
    }
  }

  // Define edges
  for (const edge of edges) {
    const srcId = nodeMap.get(edge.source);
    const tgtId = nodeMap.get(edge.target);
    if (!srcId || !tgtId) continue;

    const data = edge.data || {};
    const label = data.label || "";
    const protocol = data.protocol ? `[${data.protocol}]` : "";
    const edgeLabel = label ? `${label} ${protocol}` : protocol;
    const arrowType = data.flowKind === "async" ? "-->" : "->";

    if (edgeLabel) {
      lines.push(`${srcId} ${arrowType} ${tgtId} : ${edgeLabel}`);
    } else {
      lines.push(`${srcId} ${arrowType} ${tgtId}`);
    }
  }

  lines.push("@enduml");
  return lines.join("\n");
}

/** SVG export from the canvas ÔÇö clean, vector, board-ready. */

import type { Edge, Node } from "@xyflow/react";
import type { CanvasNodeData } from "./types";
import type { BoardExportMeta } from "./export-board";
import { renderLegendHtml, renderTitleBlockHtml } from "./export-board";

const NS = "http://www.w3.org/2000/svg";

function el(tag: string, attrs: Record<string, string> = {}) {
  const e = document.createElementNS(NS, tag);
  for (const [k, v] of Object.entries(attrs)) e.setAttribute(k, v);
  return e;
}

function textNode(content: string, attrs: Record<string, string> = {}) {
  const t = document.createElementNS(NS, "text");
  for (const [k, v] of Object.entries(attrs)) t.setAttribute(k, v);
  t.textContent = content;
  return t;
}

function svgForNodes(nodes: Node<CanvasNodeData>[], opts?: { width?: number; height?: number; padding?: number }) {
  const W = opts?.width ?? 1600;
  const H = opts?.height ?? 900;
  const P = opts?.padding ?? 48;
  const svg = el("svg", {
    xmlns: NS,
    width: String(W),
    height: String(H),
    viewBox: `0 0 ${W} ${H}`,
  });

  // Background
  svg.appendChild(el("rect", { x: "0", y: "0", width: String(W), height: String(H), fill: "#070b10" }));

  // Nodes
  for (const n of nodes) {
    const x = Math.max(P, Math.min(W - P, n.position.x));
    const y = Math.max(P, Math.min(H - P, n.position.y));
    const w = Number(n.width ?? 220);
    const h = Number(n.height ?? 88);
    const label = n.data.label ?? "";
    const kind = n.data.kind ?? "";

    svg.appendChild(
      el("rect", {
        x: String(x),
        y: String(y),
        width: String(w),
        height: String(h),
        rx: "12",
        fill: "#121821",
        stroke: "#334155",
        "stroke-width": "1.5",
      }),
    );
    svg.appendChild(
      textNode(label, {
        x: String(x + 16),
        y: String(y + 28),
        fill: "#f1f5f9",
        "font-size": "14",
        "font-family": "system-ui, sans-serif",
        "font-weight": "600",
      }),
    );
    if (kind) {
      svg.appendChild(
        textNode(kind.toUpperCase(), {
          x: String(x + 16),
          y: String(y + 44),
          fill: "#94a3b8",
          "font-size": "10",
          "font-family": "system-ui, sans-serif",
        }),
      );
    }
  }

  return svg;
}

export function renderSvg(nodes: Node<CanvasNodeData>[], edges: Edge[], opts: { title: string; width?: number; height?: number } = { title: "Arquitetura" }) {
  const W = opts.width ?? 1600;
  const H = opts.height ?? 900;
  const svg = svgForNodes(nodes, { width: W, height: H });

  // Title block
  const footer = el("g", { transform: `translate(24, ${H - 80})` });
  footer.appendChild(textNode(opts.title, { fill: "#f1f5f9", "font-size": "16", "font-weight": "600" }));
  footer.appendChild(textNode("Archia ÔÇö System Design Editor", { x: "0", y: "24", fill: "#94a3b8", "font-size": "11" }));
  svg.appendChild(footer);

  return new XMLSerializer().serializeToString(svg);
}

export function downloadSvg(svg: string, filename: string): void {
  const blob = new Blob([svg], { type: "image/svg+xml;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

